  WORKER = 'WORKER'
}

export enum FollowUpStatus {
  NEEDS_FOLLOW_UP = 'Needs Follow-up',
  CONTACTED = 'Contacted',
  SCHEDULED = 'Follow-up Scheduled',
  JOINED_UNIT = 'Joined a Unit',
  NOT_INTERESTED = 'Not Interested',
  NO_RESPONSE = 'No Response',
  CONVERTED = 'Converted to Member'
}

export enum TaskStatus {
  IN_PROGRESS = 'In Progress',
  DONE = 'Done',
  SUSPENDED = 'Suspended'
}

export enum Priority {
  HIGH = 'High',
  MEDIUM = 'Medium',
  LOW = 'Low'
}

export interface Church {
  id: string;
  name: string;
  location: string;
  adminId: string;
  createdAt: string;
}

export interface User {
  id: string;
  churchId: string;
  fullName: string;
  email: string;
  role: UserRole;
  unitId?: string;
  status: 'PENDING' | 'APPROVED';
  dateOfBirth?: string;
  anniversaryDate?: string;
}

export interface Unit {
  id: string;
  churchId: string;
  name: string;
  headIds: string[];
}

export interface FirstTimer {
  id: string;
  churchId: string;
  fullName: string;
  phone: string;
  email?: string;
  dateVisited: string;
  invitedBy?: string;
  assignedTo?: string; // Worker ID
  status: FollowUpStatus;
  notes: string;
  history: FollowUpLog[];
}

export interface FollowUpLog {
  id: string;
  date: string;
  action: string;
  performedBy: string;
}

export interface ActionPlan {
  id: string;
  churchId: string;
  unitId: string;
  title: string;
  description: string;
  startDate: string;
  endDate: string;
  assignedTo: string; // User ID
  priority: Priority;
  status: TaskStatus;
}

export interface AttendanceRecord {
  id: string;
  churchId: string;
  date: string;
  total: number;
  male: number;
  female: number;
  children: number;
}

export interface Announcement {
  id: string;
  churchId: string;
  unitId?: string; // If null, it's global for church
  title: string;
  body: string;
  expiryDate?: string;
  createdAt: string;
}

export interface Property {
  id: string;
  churchId: string;
