import React, { useState } from 'react';
import { AppProvider, useApp } from './store';
import Layout from './components/Layout';
import Dashboard from './pages/Dashboard';
import FirstTimers from './pages/FirstTimers';
import Attendance from './pages/Attendance';
import SuperAdmin from './pages/SuperAdmin';
import Login from './pages/Login';

const AppContent: React.FC = () => {
  const { currentUser } = useApp();
  const [activeTab, setActiveTab] = useState('dashboard');

  if (!currentUser) {
    return <Login />;
  }

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard': return <Dashboard />;
      case 'first-timers': return <FirstTimers />;
      case 'attendance': return <Attendance />;
      case 'superadmin': return <SuperAdmin />;
      case 'tasks': return <div className="p-12 text-center text-slate-400 border-2 border-dashed rounded-xl">Action Plans Module Under Construction</div>;
      case 'units': return <div className="p-12 text-center text-slate-400 border-2 border-dashed rounded-xl">Units Management Module Under Construction</div>;
      case 'inventory': return <div className="p-12 text-center text-slate-400 border-2 border-dashed rounded-xl">Property Tracking Module Under Construction</div>;
      case 'announcements': return <div className="p-12 text-center text-slate-400 border-2 border-dashed rounded-xl">Announcements Module Under Construction</div>;
      case 'events': return <div className="p-12 text-center text-slate-400 border-2 border-dashed rounded-xl">Calendar Module Under Construction</div>;
      default: return <Dashboard />;
    }
  };

  return (
    <Layout activeTab={activeTab} setActiveTab={setActiveTab}>
      {renderContent()}
    </Layout>
  );
};

const App: React.FC = () => {
  return (
    <AppProvider>
      <AppContent />
    </AppProvider>
  );
};

export default App;

