import React, { useState } from 'react';
import { useApp } from '../store';
import { UserRole, Property, Unit } from '../types';

const Properties: React.FC = () => {
  const { properties, units, currentUser, addProperty, updateProperty, deleteProperty } = useApp();
  const [showAddModal, setShowAddModal] = useState(false);
  const [editingProp, setEditingProp] = useState<Property | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [unitFilter, setUnitFilter] = useState('ALL');

  const isAdmin = currentUser?.role === UserRole.CHURCH_ADMIN;
  const isUnitHead = currentUser?.role === UserRole.UNIT_HEAD;

  const churchProps = properties.filter(p => p.churchId === currentUser?.churchId);
  const filteredProps = churchProps.filter(p => {
    const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesUnit = unitFilter === 'ALL' || p.unitId === unitFilter;

    // Logic for visibility
    if (isAdmin) return matchesSearch && matchesUnit;
    if (isUnitHead) return p.unitId === currentUser?.unitId && matchesSearch;
    return false;
  });

  const stats = {
    total: filteredProps.length,
    totalQuantity: filteredProps.reduce((acc, curr) => acc + curr.quantity, 0),
    maintenance: filteredProps.filter(p => p.status === 'Maintenance').length,
    damaged: filteredProps.filter(p => p.status === 'Damaged').length
  };

  const handleCreateOrUpdate = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const name = formData.get('name') as string;
    const quantity = parseInt(formData.get('quantity') as string);
    const unitId = formData.get('unitId') as string;
    const status = formData.get('status') as any;

    if (editingProp) {
      updateProperty(editingProp.id, { name, quantity, unitId, status });
    } else {
      addProperty({
        churchId: currentUser!.churchId,
        name,
        quantity,
        unitId,
        status
      });
    }
    setShowAddModal(false);
    setEditingProp(null);
  };

  const getStatusStyle = (status: string) => {
    switch (status) {
      case 'Functional': return 'bg-emerald-100 text-emerald-700';
      case 'Maintenance': return 'bg-amber-100 text-amber-700';
      case 'Damaged': return 'bg-rose-100 text-rose-700';
      default: return 'bg-slate-100 text-slate-700';
    }
  };

  return (
    <div className="space-y-8">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h3 className="text-2xl font-bold text-slate-800">Church Properties</h3>
          <p className="text-slate-500">Inventory and equipment management</p>
        </div>
        <button 
          onClick={() => setShowAddModal(true)}
          className="bg-indigo-600 text-white px-6 py-2.5 rounded-xl hover:bg-indigo-700 transition shadow-lg shadow-indigo-100 font-semibold flex items-center gap-2 w-fit"
        >
          <span className="text-xl">+</span> Add Asset
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
          <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">Total Assets</p>
          <p className="text-2xl font-black text-slate-800">{stats.totalQuantity} <span className="text-xs font-normal text-slate-400">in {stats.total} categories</span></p>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
          <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">Functional</p>
          <p className="text-2xl font-black text-emerald-600">{filteredProps.filter(p => p.status === 'Functional').length}</p>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
          <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">In Maintenance</p>
          <p className="text-2xl font-black text-amber-600">{stats.maintenance}</p>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
          <p className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1">Damaged</p>
          <p className="text-2xl font-black text-rose-600">{stats.damaged}</p>
        </div>
      </div>

      <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-6 border-b border-slate-100 flex flex-col sm:flex-row gap-4 justify-between items-center">
          <div className="relative w-full sm:w-80">
            <span className="absolute left-3 top-1/2 -translate-y-1/2">🔍</span>
            <input 
              type="text" 
              placeholder="Search equipment..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none text-sm"
            />
          </div>
          {isAdmin && (
            <select 
              value={unitFilter}
              onChange={(e) => setUnitFilter(e.target.value)}
              className="w-full sm:w-48 p-2 bg-slate-50 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-indigo-500 text-sm"
            >
              <option value="ALL">All Units</option>
              {units.filter(u => u.churchId === currentUser?.churchId).map(u => (
                <option key={u.id} value={u.id}>{u.name}</option>
              ))}
            </select>
          )}
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead className="bg-slate-50">
              <tr className="text-slate-400 text-[10px] uppercase tracking-widest font-black">
                <th className="px-8 py-4">Item Name</th>
                <th className="px-8 py-4">Unit</th>
                <th className="px-8 py-4">Quantity</th>
                <th className="px-8 py-4">Status</th>
                <th className="px-8 py-4 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredProps.map(prop => (
                <tr key={prop.id} className="hover:bg-slate-50/50 transition-colors">
                  <td className="px-8 py-4">
                    <p className="font-bold text-slate-800">{prop.name}</p>
                    <p className="text-[10px] text-slate-400">ID: {prop.id}</p>
                  </td>
                  <td className="px-8 py-4">
                    <span className="text-xs font-semibold text-indigo-600 bg-indigo-50 px-2 py-1 rounded-lg">
                      {units.find(u => u.id === prop.unitId)?.name || 'Unknown Unit'}
                    </span>
                  </td>
                  <td className="px-8 py-4 text-sm font-bold text-slate-600">{prop.quantity}</td>
                  <td className="px-8 py-4">
                    <span className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase ${getStatusStyle(prop.status)}`}>
                      {prop.status}
                    </span>
                  </td>
                  <td className="px-8 py-4 text-right">
                    <div className="flex justify-end gap-2">
                      <button 
                        onClick={() => {
                          setEditingProp(prop);
                          setShowAddModal(true);
                        }}
                        className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all"
                      >✏️</button>
                      <button 
                        onClick={() => {
                          if (confirm('Permanently remove this item from inventory?')) {
                            deleteProperty(prop.id);
                          }
                        }}
                        className="p-2 text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-all"
                      >🗑️</button>
                    </div>
                  </td>
                </tr>
              ))}
              {filteredProps.length === 0 && (
                <tr>
                  <td colSpan={5} className="px-8 py-20 text-center text-slate-400 italic">
                    No assets found in inventory.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {(showAddModal || editingProp) && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-3xl w-full max-w-md p-8 shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-2xl font-bold text-slate-800">
                {editingProp ? 'Edit Asset' : 'New Asset Registration'}
              </h2>
              <button 
                onClick={() => {
                  setShowAddModal(false);
                  setEditingProp(null);
                }} 
                className="text-slate-400 hover:text-slate-600 text-xl"
              >✕</button>
            </div>

            <form onSubmit={handleCreateOrUpdate} className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Item Name</label>
                <input 
                  required 
                  name="name" 
                  defaultValue={editingProp?.name}
                  placeholder="e.g., Wireless Mic Set" 
                  className="w-full border-slate-200 rounded-xl p-3 focus:ring-2 focus:ring-indigo-500 focus:outline-none border bg-slate-50" 
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Quantity</label>
                  <input 
                    required 
                    name="quantity" 
                    type="number"
                    min="1"
                    defaultValue={editingProp?.quantity || 1}
                    className="w-full border-slate-200 rounded-xl p-3 focus:ring-2 focus:ring-indigo-500 focus:outline-none border bg-slate-50" 
                  />
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Current Status</label>
                  <select 
                    name="status" 
                    defaultValue={editingProp?.status || 'Functional'}
                    className="w-full border-slate-200 rounded-xl p-3 border bg-slate-50 focus:outline-none focus:ring-2 focus:ring-indigo-500"
                  >
                    <option value="Functional">Functional</option>
                    <option value="Maintenance">Maintenance</option>
                    <option value="Damaged">Damaged</option>
                  </select>
                </div>
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Assign to Unit</label>
                <select 
                  name="unitId" 
                  disabled={isUnitHead}
                  defaultValue={editingProp?.unitId || (isUnitHead ? currentUser?.unitId : '')}
                  required
                  className="w-full border-slate-200 rounded-xl p-3 border bg-slate-50 focus:outline-none focus:ring-2 focus:ring-indigo-500 disabled:opacity-60"
                >
                  <option value="" disabled>Select Unit</option>
                  {units.filter(u => u.churchId === currentUser?.churchId).map(u => (
                    <option key={u.id} value={u.id}>{u.name}</option>
                  ))}
                </select>
              </div>

              <div className="flex gap-4 pt-4">
                <button 
                  type="button" 
                  onClick={() => {
                    setShowAddModal(false);
                    setEditingProp(null);
                  }} 
                  className="flex-1 px-6 py-3 border border-slate-200 text-slate-600 rounded-xl hover:bg-slate-50 font-bold"
                >Cancel</button>
                <button 
                  type="submit" 
                  className="flex-1 px-6 py-3 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 font-bold shadow-lg shadow-indigo-100"
                >
                  {editingProp ? 'Update Asset' : 'Add to Inventory'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Properties;

import React, { useState } from 'react';
