import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { 
  User, Church, Unit, FirstTimer, AttendanceRecord, ActionPlan, 
  Announcement, Property, ChurchEvent, UserRole 
} from './types';
import * as Mocks from './mockData';

interface AppState {
  currentUser: User | null;
  currentChurch: Church | null;
  churches: Church[];
  users: User[];
  units: Unit[];
  firstTimers: FirstTimer[];
  attendance: AttendanceRecord[];
  tasks: ActionPlan[];
  announcements: Announcement[];
  properties: Property[];
  events: ChurchEvent[];
}

interface AppContextProps extends AppState {
  login: (email: string) => void;
  logout: () => void;
  setCurrentChurchId: (id: string) => void;
  updateUser: (user: Partial<User>) => void;
  approveUser: (userId: string) => void;
  addFirstTimer: (ft: Omit<FirstTimer, 'id'>) => void;
  updateFirstTimer: (id: string, updates: Partial<FirstTimer>) => void;
  addAttendance: (record: Omit<AttendanceRecord, 'id'>) => void;
  addTask: (task: Omit<ActionPlan, 'id'>) => void;
  updateTask: (id: string, status: any) => void;
  addUnit: (unit: Omit<Unit, 'id'>) => void;
  updateUnit: (id: string, updates: Partial<Unit>) => void;
  deleteUnit: (id: string) => void;
  addProperty: (prop: Omit<Property, 'id'>) => void;
  updateProperty: (id: string, updates: Partial<Property>) => void;
  deleteProperty: (id: string) => void;
  addAnnouncement: (ann: Omit<Announcement, 'id' | 'createdAt'>) => void;
  updateAnnouncement: (id: string, updates: Partial<Announcement>) => void;
  deleteAnnouncement: (id: string) => void;
  addEvent: (event: Omit<ChurchEvent, 'id'>) => void;
  updateEvent: (id: string, updates: Partial<ChurchEvent>) => void;
  deleteEvent: (id: string) => void;
}

const AppContext = createContext<AppContextProps | undefined>(undefined);

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('ecclesia_state');
    if (saved) return JSON.parse(saved);
    return {
      currentUser: null,
      currentChurch: null,
      churches: Mocks.MOCK_CHURCHES,
      users: Mocks.MOCK_USERS as any,
      units: Mocks.MOCK_UNITS,
      firstTimers: Mocks.MOCK_FIRST_TIMERS as any,
      attendance: Mocks.MOCK_ATTENDANCE,
      tasks: Mocks.MOCK_TASKS as any,
      announcements: Mocks.MOCK_ANNOUNCEMENTS as any,
      properties: Mocks.MOCK_PROPERTIES as any,
      events: Mocks.MOCK_EVENTS as any,
    };
  });

  useEffect(() => {
    localStorage.setItem('ecclesia_state', JSON.stringify(state));
  }, [state]);

  const login = (email: string) => {
    const user = state.users.find(u => u.email === email);
    if (user) {
      const church = state.churches.find(c => c.id === user.churchId) || null;
      setState(prev => ({ ...prev, currentUser: user, currentChurch: church }));
    }
  };

  const logout = () => {
    setState(prev => ({ ...prev, currentUser: null, currentChurch: null }));
  };

  const setCurrentChurchId = (id: string) => {
     const church = state.churches.find(c => c.id === id) || null;
     setState(prev => ({ ...prev, currentChurch: church }));
  }

  const approveUser = (userId: string) => {
    setState(prev => ({
      ...prev,
      users: prev.users.map(u => u.id === userId ? { ...u, status: 'APPROVED' } : u)
    }));
  };

  const addFirstTimer = (ft: Omit<FirstTimer, 'id'>) => {
    const newFT = { ...ft, id: Math.random().toString(36).substr(2, 9) };
    setState(prev => ({ ...prev, firstTimers: [newFT as any, ...prev.firstTimers] }));
  };

  const updateFirstTimer = (id: string, updates: Partial<FirstTimer>) => {
    setState(prev => ({
      ...prev,
      firstTimers: prev.firstTimers.map(f => f.id === id ? { ...f, ...updates } : f)
    }));
  };

  const addAttendance = (record: Omit<AttendanceRecord, 'id'>) => {
    const newRecord = { ...record, id: Math.random().toString(36).substr(2, 9) };
    setState(prev => ({ ...prev, attendance: [newRecord as any, ...prev.attendance] }));
  };

  const addTask = (task: Omit<ActionPlan, 'id'>) => {
    const newTask = { ...task, id: Math.random().toString(36).substr(2, 9) };
    setState(prev => ({ ...prev, tasks: [newTask as any, ...prev.tasks] }));
  };

  const updateTask = (id: string, status: any) => {
    setState(prev => ({
      ...prev,
      tasks: prev.tasks.map(t => t.id === id ? { ...t, status } : t)
    }));
  }

  const addUnit = (unit: Omit<Unit, 'id'>) => {
    const newUnit = { ...unit, id: Math.random().toString(36).substr(2, 9) };
    setState(prev => ({ ...prev, units: [...prev.units, newUnit] }));
  };

  const updateUnit = (id: string, updates: Partial<Unit>) => {
    setState(prev => ({
      ...prev,
      units: prev.units.map(u => u.id === id ? { ...u, ...updates } : u)
    }));
  };

  const deleteUnit = (id: string) => {
    setState(prev => ({
      ...prev,
      units: prev.units.filter(u => u.id !== id)
    }));
  };

  const addProperty = (prop: Omit<Property, 'id'>) => {
    const newProp = { ...prop, id: Math.random().toString(36).substr(2, 9) };
    setState(prev => ({ ...prev, properties: [...prev.properties, newProp as any] }));
  };

  const updateProperty = (id: string, updates: Partial<Property>) => {
    setState(prev => ({
      ...prev,
      properties: prev.properties.map(p => p.id === id ? { ...p, ...updates } : p)
    }));
  };

  const deleteProperty = (id: string) => {
    setState(prev => ({
      ...prev,
      properties: prev.properties.filter(p => p.id !== id)
    }));
  };

  const addAnnouncement = (ann: Omit<Announcement, 'id' | 'createdAt'>) => {
    const newAnn = { 
      ...ann, 
      id: Math.random().toString(36).substr(2, 9),
      createdAt: new Date().toISOString().split('T')[0]
    };
    setState(prev => ({ ...prev, announcements: [newAnn as any, ...prev.announcements] }));
  };

  const updateAnnouncement = (id: string, updates: Partial<Announcement>) => {
    setState(prev => ({
      ...prev,
      announcements: prev.announcements.map(a => a.id === id ? { ...a, ...updates } : a)
    }));
  };

  const deleteAnnouncement = (id: string) => {
    setState(prev => ({
      ...prev,
      announcements: prev.announcements.filter(a => a.id !== id)
    }));
  };

  const addEvent = (event: Omit<ChurchEvent, 'id'>) => {
    const newEvent = { 
      ...event, 
      id: Math.random().toString(36).substr(2, 9) 
    };
    setState(prev => ({ ...prev, events: [newEvent as any, ...prev.events] }));
  };

  const updateEvent = (id: string, updates: Partial<ChurchEvent>) => {
    setState(prev => ({
      ...prev,
      events: prev.events.map(e => e.id === id ? { ...e, ...updates } : e)
    }));
  };

  const deleteEvent = (id: string) => {
    setState(prev => ({
      ...prev,
      events: prev.events.filter(e => e.id !== id)
    }));
  };

  const updateUser = (user: Partial<User>) => {};

  return (
    <AppContext.Provider value={{ 
      ...state, 
      login, 
      logout, 
      setCurrentChurchId, 
      updateUser, 
      approveUser, 
      addFirstTimer, 
      updateFirstTimer, 
      addAttendance,
      addTask,
      updateTask,
      addUnit,
      updateUnit,
      deleteUnit,
      addProperty,
      updateProperty,
      deleteProperty,
      addAnnouncement,
      updateAnnouncement,
      deleteAnnouncement,
      addEvent,
      updateEvent,
      deleteEvent
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error('useApp must be used within an AppProvider');
  return context;
};

import React, { useState } from 'react';
import { useApp } from '../store';
import { UserRole, ChurchEvent } from '../types';

const Events: React.FC = () => {
  const { events, currentUser, addEvent, updateEvent, deleteEvent } = useApp();
  const [view, setView] = useState<'LIST' | 'CALENDAR'>('LIST');
  const [showAddModal, setShowAddModal] = useState(false);
  const [editingEvent, setEditingEvent] = useState<ChurchEvent | null>(null);

  const isAdmin = currentUser?.role === UserRole.CHURCH_ADMIN;
  const isUnitHead = currentUser?.role === UserRole.UNIT_HEAD;
  const canManage = isAdmin || isUnitHead;

  const churchEvents = events.filter(e => e.churchId === currentUser?.churchId);
  const sortedEvents = [...churchEvents].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

  // Calendar Logic
  const today = new Date();
  const [currentMonth, setCurrentMonth] = useState(new Date().getMonth());
  const [currentYear, setCurrentYear] = useState(new Date().getFullYear());

  const daysInMonth = (month: number, year: number) => new Date(year, month + 1, 0).getDate();
  const startDayOfMonth = (month: number, year: number) => new Date(year, month, 1).getDay();

  const monthNames = [
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December"
  ];

  const handlePrevMonth = () => {
    if (currentMonth === 0) {
      setCurrentMonth(11);
      setCurrentYear(currentYear - 1);
    } else {
      setCurrentMonth(currentMonth - 1);
    }
  };

  const handleNextMonth = () => {
    if (currentMonth === 11) {
      setCurrentMonth(0);
      setCurrentYear(currentYear + 1);
    } else {
      setCurrentMonth(currentMonth + 1);
    }
  };

  const handleCreateOrUpdate = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const title = formData.get('title') as string;
    const date = formData.get('date') as string;
    const location = formData.get('location') as string;
    const description = formData.get('description') as string;

    if (editingEvent) {
      updateEvent(editingEvent.id, { title, date, location, description });
    } else {
      addEvent({
        churchId: currentUser!.churchId,
        title,
        date,
        location,
        description
      });
    }
    setShowAddModal(false);
    setEditingEvent(null);
  };

  return (
    <div className="space-y-8">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h3 className="text-2xl font-bold text-slate-800">Events & Calendar</h3>
          <p className="text-slate-500">Scheduled activities and special services</p>
        </div>
        <div className="flex items-center gap-3">
          <div className="bg-white p-1 rounded-xl border border-slate-200 flex shadow-sm">
            <button 
              onClick={() => setView('LIST')}
              className={`px-4 py-2 rounded-lg text-xs font-bold transition-all ${view === 'LIST' ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:text-slate-600'}`}
            >
              List View
            </button>
            <button 
              onClick={() => setView('CALENDAR')}
              className={`px-4 py-2 rounded-lg text-xs font-bold transition-all ${view === 'CALENDAR' ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:text-slate-600'}`}
            >
              Calendar
            </button>
          </div>
          {canManage && (
            <button 
              onClick={() => setShowAddModal(true)}
              className="bg-indigo-600 text-white px-6 py-2.5 rounded-xl hover:bg-indigo-700 transition shadow-lg shadow-indigo-100 font-semibold flex items-center gap-2"
            >
              <span className="text-xl">+</span> Add Event
            </button>
          )}
        </div>
      </div>

      {view === 'LIST' ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {sortedEvents.map(event => (
            <div key={event.id} className="bg-white rounded-3xl border border-slate-200 shadow-sm p-6 group hover:border-indigo-300 transition-all flex flex-col">
              <div className="flex justify-between items-start mb-4">
                <div className="bg-indigo-50 text-indigo-600 p-3 rounded-2xl">
                   <span className="text-xl">📅</span>
                </div>
                {canManage && (
                  <div className="flex gap-2">
                    <button 
                      onClick={() => {
                        setEditingEvent(event);
                        setShowAddModal(true);
                      }}
                      className="p-2 text-slate-300 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-colors"
                    >
                      ✏️
                    </button>
                    <button 
                      onClick={() => {
                        if (confirm('Cancel this event?')) deleteEvent(event.id);
                      }}
                      className="p-2 text-slate-300 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-colors"
                    >
                      🗑️
                    </button>
                  </div>
                )}
              </div>

              <h4 className="text-lg font-bold text-slate-800 mb-2">{event.title}</h4>
              <p className="text-sm text-slate-500 mb-6 flex-1 line-clamp-3">{event.description}</p>

              <div className="space-y-3 pt-4 border-t border-slate-50">
                <div className="flex items-center gap-3 text-xs text-slate-600">
                  <span className="opacity-60">🕒</span>
                  <span className="font-semibold">{event.date}</span>
                </div>
                <div className="flex items-center gap-3 text-xs text-slate-600">
                  <span className="opacity-60">📍</span>
                  <span className="font-semibold">{event.location}</span>
                </div>
              </div>
            </div>
          ))}
          {sortedEvents.length === 0 && (
            <div className="col-span-full py-24 text-center bg-slate-50 rounded-3xl border-2 border-dashed border-slate-200">
               <span className="text-5xl mb-4 block">🏜️</span>
               <p className="text-slate-500 font-bold">No upcoming events found.</p>
            </div>
          )}
        </div>
      ) : (
        <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden p-8">
          <div className="flex items-center justify-between mb-8">
            <h4 className="text-xl font-black text-slate-800">{monthNames[currentMonth]} {currentYear}</h4>
            <div className="flex gap-2">
              <button onClick={handlePrevMonth} className="p-2 hover:bg-slate-100 rounded-lg">◀</button>
              <button onClick={() => { setCurrentMonth(today.getMonth()); setCurrentYear(today.getFullYear()); }} className="px-4 py-2 text-xs font-bold text-indigo-600 bg-indigo-50 rounded-lg">Today</button>
              <button onClick={handleNextMonth} className="p-2 hover:bg-slate-100 rounded-lg">▶</button>
            </div>
          </div>

          <div className="grid grid-cols-7 gap-4">
            {["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].map(day => (
              <div key={day} className="text-center text-[10px] font-black uppercase tracking-widest text-slate-400 pb-4">{day}</div>
            ))}

            {Array.from({ length: startDayOfMonth(currentMonth, currentYear) }).map((_, i) => (
              <div key={`empty-${i}`} className="aspect-square"></div>
            ))}

            {Array.from({ length: daysInMonth(currentMonth, currentYear) }).map((_, i) => {
              const dayNum = i + 1;
              const dateString = `${currentYear}-${String(currentMonth + 1).padStart(2, '0')}-${String(dayNum).padStart(2, '0')}`;
              const dayEvents = churchEvents.filter(e => e.date.startsWith(dateString));
              const isToday = today.getDate() === dayNum && today.getMonth() === currentMonth && today.getFullYear() === currentYear;

              return (
                <div key={dayNum} className={`aspect-square border border-slate-50 rounded-2xl flex flex-col items-center justify-center relative transition-colors cursor-default ${isToday ? 'bg-indigo-600 text-white' : 'hover:bg-indigo-50/50'}`}>
                  <span className={`text-sm font-bold ${isToday ? '' : 'text-slate-700'}`}>{dayNum}</span>
                  {dayEvents.length > 0 && (
                    <div className="flex gap-0.5 mt-1">
                      {dayEvents.map(e => (
                        <div key={e.id} className={`w-1 h-1 rounded-full ${isToday ? 'bg-white' : 'bg-indigo-500'}`}></div>
                      ))}
                    </div>
                  )}
                  {dayEvents.length > 0 && (
                     <div className="absolute inset-0 opacity-0 hover:opacity-100 bg-white/95 backdrop-blur-sm p-2 rounded-2xl flex flex-col justify-center items-center text-[10px] text-slate-800 transition-opacity z-10 border border-indigo-100">
                        {dayEvents.map(e => <p key={e.id} className="truncate w-full text-center font-bold">· {e.title}</p>)}
                     </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}

      {(showAddModal || editingEvent) && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-3xl w-full max-w-md p-8 shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-2xl font-bold text-slate-800">
                {editingEvent ? 'Modify Event' : 'Schedule New Event'}
              </h2>
              <button onClick={() => { setShowAddModal(false); setEditingEvent(null); }} className="text-slate-400 hover:text-slate-600 text-xl">✕</button>
            </div>

            <form onSubmit={handleCreateOrUpdate} className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Event Title</label>
                <input required name="title" defaultValue={editingEvent?.title} placeholder="e.g., Youth Worship Encounter" className="w-full border-slate-200 rounded-xl p-3 focus:ring-2 focus:ring-indigo-500 focus:outline-none border bg-slate-50" />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Date & Time</label>
                  <input required name="date" type="datetime-local" defaultValue={editingEvent?.date} className="w-full border-slate-200 rounded-xl p-3 border bg-slate-50 focus:outline-none focus:ring-2 focus:ring-indigo-500" />
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Location</label>
                  <input required name="location" defaultValue={editingEvent?.location} placeholder="Main Hall" className="w-full border-slate-200 rounded-xl p-3 border bg-slate-50 focus:outline-none focus:ring-2 focus:ring-indigo-500" />
                </div>
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase tracking-wider mb-2">Brief Description</label>
                <textarea required name="description" rows={3} defaultValue={editingEvent?.description} placeholder="What should attendees expect?" className="w-full border-slate-200 rounded-xl p-3 focus:ring-2 focus:ring-indigo-500 focus:outline-none border bg-slate-50"></textarea>
              </div>

              <div className="flex gap-4 pt-6">
                <button type="button" onClick={() => { setShowAddModal(false); setEditingEvent(null); }} className="flex-1 px-6 py-3 border border-slate-200 text-slate-600 rounded-xl hover:bg-slate-50 font-bold">Cancel</button>
                <button type="submit" className="flex-1 px-6 py-3 bg-indigo-600 text-white rounded-xl hover:bg-indigo-700 font-bold shadow-lg shadow-indigo-100">
                  {editingEvent ? 'Update Schedule' : 'Confirm Event'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Events;

import React, { useState } from 'react';
import { AppProvider, useApp } from './store';
import Layout from './components/Layout';
import Dashboard from './pages/Dashboard';
import FirstTimers from './pages/FirstTimers';
import Attendance from './pages/Attendance';
import SuperAdmin from './pages/SuperAdmin';
