import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { 
  User, Church, Unit, FirstTimer, AttendanceRecord, ActionPlan, 
  Announcement, Property, ChurchEvent, UserRole, Transaction, Budget, Currency 
} from './types';
import * as Mocks from './mockData';

// Mock Exchange Rates relative to 1 USD
export const EXCHANGE_RATES: Record<Currency, number> = {
  [Currency.USD]: 1,
  [Currency.NGN]: 1500,
  [Currency.GBP]: 0.78
};

interface AppState {
  currentUser: User | null;
  currentChurch: Church | null;
  churches: Church[];
  users: User[];
  units: Unit[];
  firstTimers: FirstTimer[];
  attendance: AttendanceRecord[];
  tasks: ActionPlan[];
  announcements: Announcement[];
  properties: Property[];
  events: ChurchEvent[];
  transactions: Transaction[];
  budgets: Budget[];
}

interface AppContextProps extends AppState {
  login: (email: string) => void;
  logout: () => void;
  setCurrentChurchId: (id: string) => void;
  updateUser: (user: Partial<User>) => void;
  approveUser: (userId: string) => void;
  addFirstTimer: (ft: Omit<FirstTimer, 'id'>) => void;
  updateFirstTimer: (id: string, updates: Partial<FirstTimer>) => void;
  addAttendance: (record: Omit<AttendanceRecord, 'id'>) => void;
  addTask: (task: Omit<ActionPlan, 'id'>) => void;
  updateTask: (id: string, status: any) => void;
  addUnit: (unit: Omit<Unit, 'id'>) => void;
  updateUnit: (id: string, updates: Partial<Unit>) => void;
  deleteUnit: (id: string) => void;
  addProperty: (prop: Omit<Property, 'id'>) => void;
  updateProperty: (id: string, updates: Partial<Property>) => void;
  deleteProperty: (id: string) => void;
  addAnnouncement: (ann: Omit<Announcement, 'id' | 'createdAt'>) => void;
  updateAnnouncement: (id: string, updates: Partial<Announcement>) => void;
  deleteAnnouncement: (id: string) => void;
  addEvent: (event: Omit<ChurchEvent, 'id'>) => void;
  updateEvent: (id: string, updates: Partial<ChurchEvent>) => void;
  deleteEvent: (id: string) => void;
  addTransaction: (tx: Omit<Transaction, 'id'>) => void;
  addBudget: (b: Omit<Budget, 'id'>) => void;
  toggleAccountingAccess: (userId: string) => void;
  setChurchCurrency: (churchId: string, currency: Currency) => void;
}

const AppContext = createContext<AppContextProps | undefined>(undefined);

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('ecclesia_state');
    if (saved) return JSON.parse(saved);
    return {
      currentUser: null,
      currentChurch: null,
      churches: Mocks.MOCK_CHURCHES.map(c => ({ ...c, currency: Currency.USD })),
      users: Mocks.MOCK_USERS as any,
      units: Mocks.MOCK_UNITS,
      firstTimers: Mocks.MOCK_FIRST_TIMERS as any,
      attendance: Mocks.MOCK_ATTENDANCE,
      tasks: Mocks.MOCK_TASKS as any,
      announcements: Mocks.MOCK_ANNOUNCEMENTS as any,
      properties: Mocks.MOCK_PROPERTIES as any,
      events: Mocks.MOCK_EVENTS as any,
      transactions: [],
      budgets: [],
    };
  });

  useEffect(() => {
    localStorage.setItem('ecclesia_state', JSON.stringify(state));
  }, [state]);

  const login = (email: string) => {
    const user = state.users.find(u => u.email === email);
    if (user) {
      const church = state.churches.find(c => c.id === user.churchId) || null;
      setState(prev => ({ ...prev, currentUser: user, currentChurch: church }));
    }
  };

  const logout = () => {
    setState(prev => ({ ...prev, currentUser: null, currentChurch: null }));
  };

  const setCurrentChurchId = (id: string) => {
     const church = state.churches.find(c => c.id === id) || null;
     setState(prev => ({ ...prev, currentChurch: church }));
  }

  const approveUser = (userId: string) => {
    setState(prev => ({
      ...prev,
      users: prev.users.map(u => u.id === userId ? { ...u, status: 'APPROVED' } : u)
    }));
  };

  const addFirstTimer = (ft: Omit<FirstTimer, 'id'>) => {
    const newFT = { ...ft, id: Math.random().toString(36).substr(2, 9) };
    setState(prev => ({ ...prev, firstTimers: [newFT as any, ...prev.firstTimers] }));
  };

  const updateFirstTimer = (id: string, updates: Partial<FirstTimer>) => {
    setState(prev => ({
      ...prev,
      firstTimers: prev.firstTimers.map(f => f.id === id ? { ...f, ...updates } : f)
    }));
  };

  const addAttendance = (record: Omit<AttendanceRecord, 'id'>) => {
    const newRecord = { ...record, id: Math.random().toString(36).substr(2, 9) };
    setState(prev => ({ ...prev, attendance: [newRecord as any, ...prev.attendance] }));
  };

  const addTask = (task: Omit<ActionPlan, 'id'>) => {
    const newTask = { ...task, id: Math.random().toString(36).substr(2, 9) };
    setState(prev => ({ ...prev, tasks: [newTask as any, ...prev.tasks] }));
  };

  const updateTask = (id: string, status: any) => {
    setState(prev => ({
      ...prev,
      tasks: prev.tasks.map(t => t.id === id ? { ...t, status } : t)
    }));
  }

  const addUnit = (unit: Omit<Unit, 'id'>) => {
    const newUnit = { ...unit, id: Math.random().toString(36).substr(2, 9) };
    setState(prev => ({ ...prev, units: [...prev.units, newUnit] }));
  };

  const updateUnit = (id: string, updates: Partial<Unit>) => {
    setState(prev => ({
      ...prev,
      units: prev.units.map(u => u.id === id ? { ...u, ...updates } : u)
    }));
  };

  const deleteUnit = (id: string) => {
    setState(prev => ({
      ...prev,
      units: prev.units.filter(u => u.id !== id)
    }));
  };

  const addProperty = (prop: Omit<Property, 'id'>) => {
    const newProp = { ...prop, id: Math.random().toString(36).substr(2, 9) };
    setState(prev => ({ ...prev, properties: [...prev.properties, newProp as any] }));
  };

  const updateProperty = (id: string, updates: Partial<Property>) => {
    setState(prev => ({
      ...prev,
      properties: prev.properties.map(p => p.id === id ? { ...p, ...updates } : p)
    }));
  };

  const deleteProperty = (id: string) => {
    setState(prev => ({
      ...prev,
      properties: prev.properties.filter(p => p.id !== id)
    }));
  };

  const addAnnouncement = (ann: Omit<Announcement, 'id' | 'createdAt'>) => {
    const newAnn = { 
      ...ann, 
      id: Math.random().toString(36).substr(2, 9),
      createdAt: new Date().toISOString().split('T')[0]
    };
    setState(prev => ({ ...prev, announcements: [newAnn as any, ...prev.announcements] }));
  };

  const updateAnnouncement = (id: string, updates: Partial<Announcement>) => {
    setState(prev => ({
      ...prev,
      announcements: prev.announcements.map(a => a.id === id ? { ...a, ...updates } : a)
    }));
  };

  const deleteAnnouncement = (id: string) => {
    setState(prev => ({
      ...prev,
      announcements: prev.announcements.filter(a => a.id !== id)
    }));
  };

  const addEvent = (event: Omit<ChurchEvent, 'id'>) => {
    const newEvent = { 
      ...event, 
      id: Math.random().toString(36).substr(2, 9) 
    };
    setState(prev => ({ ...prev, events: [newEvent as any, ...prev.events] }));
  };

  const updateEvent = (id: string, updates: Partial<ChurchEvent>) => {
    setState(prev => ({
      ...prev,
      events: prev.events.map(e => e.id === id ? { ...e, ...updates } : e)
    }));
  };

  const deleteEvent = (id: string) => {
    setState(prev => ({
      ...prev,
      events: prev.events.filter(e => e.id !== id)
    }));
  };

  const addTransaction = (tx: Omit<Transaction, 'id'>) => {
    const newTx = { ...tx, id: Math.random().toString(36).substr(2, 9) };
    setState(prev => ({ 
      ...prev, 
      transactions: [newTx as any, ...prev.transactions],
      budgets: tx.type === 'EXPENSE' 
        ? prev.budgets.map(b => b.category === tx.category ? { ...b, spentAmount: b.spentAmount + tx.amount } : b)
        : prev.budgets
    }));
  };

  const addBudget = (b: Omit<Budget, 'id'>) => {
    const newB = { ...b, id: Math.random().toString(36).substr(2, 9) };
    setState(prev => ({ ...prev, budgets: [...prev.budgets, newB as any] }));
  };

  const toggleAccountingAccess = (userId: string) => {
    setState(prev => ({
      ...prev,
      users: prev.users.map(u => u.id === userId ? { ...u, hasAccountingAccess: !u.hasAccountingAccess } : u)
    }));
  };

  const setChurchCurrency = (churchId: string, targetCurrency: Currency) => {
    setState(prev => {
      const church = prev.churches.find(c => c.id === churchId);
      if (!church) return prev;

      const sourceCurrency = church.currency || Currency.USD;
      if (sourceCurrency === targetCurrency) return prev;

      // Conversion factor: How many of target units are in one source unit?
      // Amount_in_USD = Amount / rates[source]
      // Amount_in_Target = Amount_in_USD * rates[target]
      // Factor = rates[target] / rates[source]
      const conversionFactor = EXCHANGE_RATES[targetCurrency] / EXCHANGE_RATES[sourceCurrency];

      const updatedChurches = prev.churches.map(c => c.id === churchId ? { ...c, currency: targetCurrency } : c);
      const updatedCurrentChurch = prev.currentChurch?.id === churchId ? { ...prev.currentChurch, currency: targetCurrency } : prev.currentChurch;

      const updatedTransactions = prev.transactions.map(tx => 
        tx.churchId === churchId ? { ...tx, amount: Number((tx.amount * conversionFactor).toFixed(2)) } : tx
      );

      const updatedBudgets = prev.budgets.map(b => 
        b.churchId === churchId ? { 
          ...b, 
          allocatedAmount: Number((b.allocatedAmount * conversionFactor).toFixed(2)),
          spentAmount: Number((b.spentAmount * conversionFactor).toFixed(2))
        } : b
      );

      return {
        ...prev,
        churches: updatedChurches,
        currentChurch: updatedCurrentChurch,
        transactions: updatedTransactions,
        budgets: updatedBudgets
      };
    });
  };

  const updateUser = (user: Partial<User>) => {};

  return (
    <AppContext.Provider value={{ 
      ...state, 
      login, 
      logout, 
      setCurrentChurchId, 
      updateUser, 
      approveUser, 
      addFirstTimer, 
      updateFirstTimer, 
      addAttendance,
      addTask,
      updateTask,
      addUnit,
      updateUnit,
      deleteUnit,
      addProperty,
      updateProperty,
      deleteProperty,
      addAnnouncement,
      updateAnnouncement,
      deleteAnnouncement,
      addEvent,
      updateEvent,
      deleteEvent,
      addTransaction,
      addBudget,
      toggleAccountingAccess,
      setChurchCurrency
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error('useApp must be used within an AppProvider');
  return context;
};

import React, { useState } from 'react';
import { useApp, EXCHANGE_RATES } from '../store';
import { UserRole, Transaction, Budget, Currency } from '../types';

const Accounting: React.FC = () => {
  const { 
    transactions, budgets, currentUser, users, currentChurch,
    addTransaction, addBudget, toggleAccountingAccess, setChurchCurrency 
  } = useApp();

  const [activeTab, setActiveTab] = useState<'OVERVIEW' | 'TRANSACTIONS' | 'BUDGETS' | 'PERMISSIONS'>('OVERVIEW');
  const [showTxModal, setShowTxModal] = useState(false);
  const [showBudgetModal, setShowBudgetModal] = useState(false);
  const [converting, setConverting] = useState(false);

  const isAdmin = currentUser?.role === UserRole.CHURCH_ADMIN;
  const currencySymbol = currentChurch?.currency || Currency.USD;

  const churchTx = transactions.filter(t => t.churchId === currentUser?.churchId);
  const churchBudgets = budgets.filter(b => b.churchId === currentUser?.churchId);
  const churchWorkers = users.filter(u => u.churchId === currentUser?.churchId && u.role === UserRole.WORKER && u.status === 'APPROVED');

  const totalIncome = churchTx.filter(t => t.type === 'INCOME').reduce((acc, curr) => acc + curr.amount, 0);
  const totalExpense = churchTx.filter(t => t.type === 'EXPENSE').reduce((acc, curr) => acc + curr.amount, 0);
  const balance = totalIncome - totalExpense;

  const handleAddTx = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    addTransaction({
      churchId: currentUser!.churchId,
      type: formData.get('type') as any,
      category: formData.get('category') as string,
      amount: parseFloat(formData.get('amount') as string),
      date: formData.get('date') as string,
      description: formData.get('description') as string,
      recordedBy: currentUser!.id
    });
    setShowTxModal(false);
  };

  const handleAddBudget = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    addBudget({
      churchId: currentUser!.churchId,
      category: formData.get('category') as string,
      allocatedAmount: parseFloat(formData.get('amount') as string),
      spentAmount: 0,
      period: formData.get('period') as string
    });
    setShowBudgetModal(false);
  };

  const handleCurrencyChange = (newCurrency: Currency) => {
    if (currentChurch && currentChurch.currency !== newCurrency) {
      setConverting(true);
      // Simulate a small delay for conversion UX
      setTimeout(() => {
        setChurchCurrency(currentChurch.id, newCurrency);
        setConverting(false);
      }, 600);
    }
  };

  return (
    <div className="space-y-8 relative">
      {converting && (
        <div className="absolute inset-0 bg-white/50 backdrop-blur-[2px] z-50 flex flex-col items-center justify-center rounded-3xl animate-in fade-in duration-300">
           <div className="w-12 h-12 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mb-4"></div>
           <p className="text-indigo-600 font-black text-xs uppercase tracking-widest">Recalculating Values...</p>
        </div>
      )}

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h3 className="text-2xl font-bold text-slate-800">Financial Management</h3>
          <p className="text-slate-500">Track tithes, expenses, and budget performance</p>
        </div>
        <div className="flex items-center gap-4">
          <div className="flex flex-col items-end gap-1 mr-2">
            <span className="text-[9px] font-black text-slate-400 uppercase tracking-tighter">Currency Base</span>
            <div className="flex bg-slate-100 p-1 rounded-xl border border-slate-200">
              {[Currency.USD, Currency.NGN, Currency.GBP].map(curr => (
                <button
                  key={curr}
                  onClick={() => handleCurrencyChange(curr)}
                  className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all ${currencySymbol === curr ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                >
                  {curr}
                </button>
              ))}
            </div>
          </div>
          <button 
            onClick={() => setShowTxModal(true)}
            className="bg-emerald-600 text-white px-5 py-2.5 rounded-xl hover:bg-emerald-700 transition shadow-lg shadow-emerald-100 font-semibold flex items-center gap-2"
          >
            <span>➕</span> Record Transaction
          </button>
        </div>
      </div>

      <div className="flex bg-white p-1 rounded-2xl border border-slate-200 shadow-sm w-fit">
        {(['OVERVIEW', 'TRANSACTIONS', 'BUDGETS', 'PERMISSIONS'] as const).map((t) => (
          (t === 'PERMISSIONS' && !isAdmin) ? null : (
            <button
              key={t}
              onClick={() => setActiveTab(t)}
              className={`px-6 py-2 rounded-xl text-xs font-black transition-all ${activeTab === t ? 'bg-indigo-600 text-white shadow-md shadow-indigo-100' : 'text-slate-400 hover:text-slate-600'}`}
            >
              {t}
            </button>
          )
        ))}
      </div>

      {activeTab === 'OVERVIEW' && (
        <div className="space-y-8">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="bg-indigo-600 p-8 rounded-3xl text-white shadow-xl shadow-indigo-100 relative overflow-hidden">
              <div className="absolute top-0 right-0 p-8 opacity-10 text-6xl italic font-black">{currencySymbol}</div>
              <p className="text-indigo-100 font-bold uppercase tracking-widest text-[10px] mb-2">Net Church Balance</p>
              <h2 className="text-4xl font-black">{currencySymbol}{balance.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</h2>
            </div>
            <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
              <p className="text-slate-400 font-bold uppercase tracking-widest text-[10px] mb-2">Total Income</p>
              <h2 className="text-3xl font-black text-emerald-600">{currencySymbol}{totalIncome.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</h2>
            </div>
            <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
              <p className="text-slate-400 font-bold uppercase tracking-widest text-[10px] mb-2">Total Expenses</p>
              <h2 className="text-3xl font-black text-rose-600">{currencySymbol}{totalExpense.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</h2>
            </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
            <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
              <div className="flex justify-between items-start mb-6">
                <h4 className="text-lg font-bold text-slate-800">Budget Compliance</h4>
                <div className="text-[10px] font-bold text-slate-400 uppercase tracking-widest bg-slate-50 px-2 py-1 rounded">Equivalent Rates Active</div>
              </div>
              <div className="space-y-6">
                {churchBudgets.map(b => {
                  const percent = Math.min((b.spentAmount / b.allocatedAmount) * 100, 100);
                  const isOver = b.spentAmount > b.allocatedAmount;
                  return (
                    <div key={b.id}>
                      <div className="flex justify-between text-xs font-bold mb-2">
                        <span className="text-slate-600">{b.category}</span>
                        <span className={isOver ? 'text-rose-600' : 'text-slate-400'}>
                          {currencySymbol}{b.spentAmount.toLocaleString()} / {currencySymbol}{b.allocatedAmount.toLocaleString()}
                        </span>
                      </div>
                      <div className="h-3 bg-slate-100 rounded-full overflow-hidden">
                        <div 
                          className={`h-full transition-all duration-500 ${isOver ? 'bg-rose-500' : 'bg-indigo-500'}`} 
                          style={{ width: `${percent}%` }}
                        ></div>
                      </div>
                    </div>
                  );
                })}
                {churchBudgets.length === 0 && (
                  <p className="text-center text-slate-400 py-8 italic text-sm">No budgets defined for this period.</p>
                )}
              </div>
            </div>

            <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm">
              <h4 className="text-lg font-bold text-slate-800 mb-6">Recent Activity</h4>
              <div className="space-y-4">
                {churchTx.slice(0, 5).map(tx => (
                  <div key={tx.id} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100 hover:border-indigo-100 transition-colors">
                    <div className="flex items-center gap-4">
                      <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-bold ${tx.type === 'INCOME' ? 'bg-emerald-100 text-emerald-600' : 'bg-rose-100 text-rose-600'}`}>
                        {tx.type === 'INCOME' ? '↓' : '↑'}
                      </div>
                      <div>
                        <p className="text-sm font-bold text-slate-800">{tx.description}</p>
                        <p className="text-[10px] text-slate-400 uppercase font-black tracking-widest">{tx.category} • {tx.date}</p>
                      </div>
                    </div>
                    <span className={`font-black text-sm ${tx.type === 'INCOME' ? 'text-emerald-600' : 'text-rose-600'}`}>
                      {tx.type === 'INCOME' ? '+' : '-'}{currencySymbol}{tx.amount.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}

      {activeTab === 'TRANSACTIONS' && (
        <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
          <table className="w-full text-left border-collapse">
            <thead className="bg-slate-50 border-b border-slate-100">
              <tr className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
                <th className="px-8 py-5">Date</th>
                <th className="px-8 py-5">Description</th>
                <th className="px-8 py-5">Category</th>
                <th className="px-8 py-5">Type</th>
                <th className="px-8 py-5 text-right">Amount ({currencySymbol})</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {churchTx.map(tx => (
                <tr key={tx.id} className="hover:bg-slate-50/50 transition-colors">
                  <td className="px-8 py-5 text-sm font-medium text-slate-500">{tx.date}</td>
                  <td className="px-8 py-5 text-sm font-bold text-slate-800">{tx.description}</td>
                  <td className="px-8 py-5 text-xs font-semibold text-slate-500 uppercase">{tx.category}</td>
                  <td className="px-8 py-5">
                    <span className={`px-3 py-1 rounded-full text-[10px] font-black uppercase ${tx.type === 'INCOME' ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'}`}>
                      {tx.type}
                    </span>
                  </td>
                  <td className={`px-8 py-5 text-right font-black text-sm ${tx.type === 'INCOME' ? 'text-emerald-600' : 'text-rose-600'}`}>
                    {tx.type === 'INCOME' ? '+' : '-'}{tx.amount.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {activeTab === 'BUDGETS' && (
        <div className="space-y-6">
          <div className="flex justify-between items-center">
            <h4 className="text-xl font-bold text-slate-800">Expense Budgets</h4>
            <button 
              onClick={() => setShowBudgetModal(true)}
              className="px-4 py-2 bg-indigo-50 text-indigo-600 text-xs font-bold rounded-xl hover:bg-indigo-100 transition"
            >
              + Define New Budget
            </button>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {churchBudgets.map(b => (
              <div key={b.id} className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm flex flex-col">
                <div className="flex justify-between mb-4">
                  <span className="text-xs font-black text-indigo-600 uppercase tracking-widest">{b.period}</span>
                  {b.spentAmount > b.allocatedAmount && <span className="bg-rose-50 text-rose-600 px-2 py-0.5 rounded text-[10px] font-black uppercase">Over Budget</span>}
                </div>
                <h5 className="text-lg font-bold text-slate-800 mb-6">{b.category}</h5>
                <div className="flex justify-between text-xs font-bold text-slate-400 mb-2">
                  <span>Spent: {currencySymbol}{b.spentAmount.toLocaleString()}</span>
                  <span>Goal: {currencySymbol}{b.allocatedAmount.toLocaleString()}</span>
                </div>
                <div className="h-3 bg-slate-50 rounded-full overflow-hidden border border-slate-100 mb-4">
                  <div 
                    className={`h-full ${b.spentAmount > b.allocatedAmount ? 'bg-rose-500' : 'bg-indigo-500'}`} 
                    style={{ width: `${Math.min((b.spentAmount / b.allocatedAmount) * 100, 100)}%` }}
                  ></div>
                </div>
                <p className="text-[10px] text-slate-400 text-center font-bold uppercase tracking-tighter">
                  {Math.round((b.spentAmount / b.allocatedAmount) * 100)}% Consumed
                </p>
              </div>
            ))}
          </div>
        </div>
      )}

      {activeTab === 'PERMISSIONS' && isAdmin && (
        <div className="bg-white rounded-3xl border border-slate-200 shadow-sm p-8">
          <h4 className="text-xl font-bold text-slate-800 mb-2">Staff Permissions</h4>
          <p className="text-sm text-slate-500 mb-8">Grant specific workers access to manage church accounting modules.</p>

          <div className="divide-y divide-slate-100">
            {churchWorkers.map(worker => (
              <div key={worker.id} className="py-4 flex items-center justify-between">
                <div className="flex items-center gap-4">
                   <div className="w-10 h-10 rounded-full bg-slate-100 flex items-center justify-center font-bold text-slate-400">{worker.fullName.charAt(0)}</div>
                   <div>
                     <p className="text-sm font-bold text-slate-800">{worker.fullName}</p>
                     <p className="text-xs text-slate-400">{worker.email}</p>
                   </div>
                </div>
                <div className="flex items-center gap-4">
                   <span className={`text-[10px] font-black uppercase tracking-widest ${worker.hasAccountingAccess ? 'text-indigo-600' : 'text-slate-300'}`}>
                     {worker.hasAccountingAccess ? 'Authorized' : 'No Access'}
                   </span>
                   <button 
                    onClick={() => toggleAccountingAccess(worker.id)}
                    className={`w-12 h-6 rounded-full p-1 transition-colors relative ${worker.hasAccountingAccess ? 'bg-indigo-600' : 'bg-slate-200'}`}
                   >
                     <div className={`w-4 h-4 bg-white rounded-full transition-transform ${worker.hasAccountingAccess ? 'translate-x-6' : 'translate-x-0'}`}></div>
                   </button>
                </div>
              </div>
            ))}
            {churchWorkers.length === 0 && (
              <p className="py-12 text-center text-slate-400 italic">No approved workers found in this church.</p>
            )}
          </div>
        </div>
      )}

      {/* Modals */}
      {showTxModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-3xl w-full max-w-md p-8 shadow-2xl animate-in zoom-in-95 duration-200">
            <h2 className="text-2xl font-bold text-slate-800 mb-6">Financial Entry</h2>
            <form onSubmit={handleAddTx} className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase tracking-widest mb-2">Type</label>
                <div className="grid grid-cols-2 gap-2 p-1 bg-slate-100 rounded-xl">
                   <label className="cursor-pointer">
                      <input type="radio" name="type" value="INCOME" defaultChecked className="hidden peer" />
                      <div className="text-center py-2 rounded-lg text-xs font-bold peer-checked:bg-white peer-checked:text-emerald-600 peer-checked:shadow-sm text-slate-500">Income</div>
                   </label>
                   <label className="cursor-pointer">
                      <input type="radio" name="type" value="EXPENSE" className="hidden peer" />
                      <div className="text-center py-2 rounded-lg text-xs font-bold peer-checked:bg-white peer-checked:text-rose-600 peer-checked:shadow-sm text-slate-500">Expense</div>
                   </label>
                </div>
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Category</label>
                <select name="category" required className="w-full border-slate-200 rounded-xl p-3 border bg-slate-50 focus:ring-2 focus:ring-indigo-500 outline-none text-sm font-semibold">
                   <option>Tithes & Offerings</option>
                   <option>Building Project</option>
                   <option>Welfare</option>
                   <option>Utility Bills</option>
                   <option>Event/Project Expense</option>
                   <option>Administrative</option>
                   <option>Other</option>
                </select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Amount ({currencySymbol})</label>
                  <input required name="amount" type="number" step="0.01" className="w-full border-slate-200 rounded-xl p-3 border bg-slate-50 focus:ring-2 focus:ring-indigo-500 outline-none font-bold" />
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Date</label>
                  <input required name="date" type="date" defaultValue={new Date().toISOString().split('T')[0]} className="w-full border-slate-200 rounded-xl p-3 border bg-slate-50 focus:ring-2 focus:ring-indigo-500 outline-none text-sm" />
                </div>
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Description</label>
                <input required name="description" placeholder="Short memo..." className="w-full border-slate-200 rounded-xl p-3 border bg-slate-50 focus:ring-2 focus:ring-indigo-500 outline-none text-sm" />
              </div>
              <div className="flex gap-4 pt-4">
                <button type="button" onClick={() => setShowTxModal(false)} className="flex-1 px-4 py-3 border border-slate-200 rounded-xl text-slate-600 font-bold hover:bg-slate-50">Cancel</button>
                <button type="submit" className="flex-1 px-4 py-3 bg-indigo-600 text-white rounded-xl font-bold shadow-lg shadow-indigo-100 hover:bg-indigo-700">Save</button>
              </div>
            </form>
          </div>
        </div>
      )}

      {showBudgetModal && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-3xl w-full max-w-md p-8 shadow-2xl animate-in zoom-in-95 duration-200">
            <h2 className="text-2xl font-bold text-slate-800 mb-6">Setup Budget</h2>
            <form onSubmit={handleAddBudget} className="space-y-4">
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Category</label>
                <input required name="category" placeholder="e.g., Youth Ministry" className="w-full border-slate-200 rounded-xl p-3 border bg-slate-50 focus:ring-2 focus:ring-indigo-500 outline-none text-sm" />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Allocated Amount ({currencySymbol})</label>
                <input required name="amount" type="number" className="w-full border-slate-200 rounded-xl p-3 border bg-slate-50 focus:ring-2 focus:ring-indigo-500 outline-none font-bold" />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Budget Period</label>
                <select name="period" className="w-full border-slate-200 rounded-xl p-3 border bg-slate-50 focus:ring-2 focus:ring-indigo-500 outline-none text-sm font-semibold">
                   <option>Monthly - May 2024</option>
                   <option>Monthly - June 2024</option>
                   <option>Annual - 2024</option>
                </select>
              </div>
              <div className="flex gap-4 pt-4">
                <button type="button" onClick={() => setShowBudgetModal(false)} className="flex-1 px-4 py-3 border border-slate-200 rounded-xl text-slate-600 font-bold hover:bg-slate-50">Cancel</button>
                <button type="submit" className="flex-1 px-4 py-3 bg-indigo-600 text-white rounded-xl font-bold shadow-lg shadow-indigo-100 hover:bg-indigo-700">Set Budget</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Accounting;

import React, { useState, useEffect } from 'react';
import { useApp } from '../store';
import { UserRole } from '../types';

interface LayoutProps {
  children: React.ReactNode;
  activeTab: string;
  setActiveTab: (tab: string) => void;
}

const Layout: React.FC<LayoutProps> = ({ children, activeTab, setActiveTab }) => {
  const { currentUser, logout, currentChurch } = useApp();
  const [isSidebarOpen, setIsSidebarOpen] = useState(true);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // Auto-close sidebar on smaller screens
  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth < 1024) {
        setIsSidebarOpen(false);
      } else {
        setIsSidebarOpen(true);
      }
    };
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  if (!currentUser) return <>{children}</>;

  const menuItems = [
    { id: 'dashboard', label: 'Dashboard', icon: '🏠', roles: [UserRole.CHURCH_ADMIN, UserRole.UNIT_HEAD, UserRole.WORKER] },
    { id: 'superadmin', label: 'Platform Mgmt', icon: '🌐', roles: [UserRole.PLATFORM_OWNER] },
    { id: 'first-timers', label: 'First Timers', icon: '👋', roles: [UserRole.CHURCH_ADMIN, UserRole.UNIT_HEAD, UserRole.WORKER] },
    { id: 'attendance', label: 'Attendance', icon: '📊', roles: [UserRole.CHURCH_ADMIN] },
    { id: 'tasks', label: 'Action Plans', icon: '📋', roles: [UserRole.CHURCH_ADMIN, UserRole.UNIT_HEAD, UserRole.WORKER] },
    { id: 'units', label: 'Church Units', icon: '⛪', roles: [UserRole.CHURCH_ADMIN] },
    { id: 'inventory', label: 'Properties', icon: '📦', roles: [UserRole.CHURCH_ADMIN, UserRole.UNIT_HEAD] },
    { id: 'announcements', label: 'Announcements', icon: '📢', roles: [UserRole.CHURCH_ADMIN, UserRole.UNIT_HEAD, UserRole.WORKER] },
    { id: 'events', label: 'Events & Calendar', icon: '📅', roles: [UserRole.CHURCH_ADMIN, UserRole.UNIT_HEAD, UserRole.WORKER] },
    { 
      id: 'accounting', 
      label: 'Financials', 
      icon: '💰', 
      roles: [UserRole.CHURCH_ADMIN], 
      customCheck: () => currentUser.hasAccountingAccess === true 
    },
  ];

  const filteredMenuItems = menuItems.filter(item => {
    const hasRole = item.roles.includes(currentUser.role);
    const hasCustomAccess = item.customCheck ? item.customCheck() : false;
    return hasRole || hasCustomAccess;
  });

  const handleTabClick = (id: string) => {
    setActiveTab(id);
    setIsMobileMenuOpen(false);
  };

  return (
    <div className="flex min-h-screen bg-slate-50">
      {/* Mobile Overlay */}
      {isMobileMenuOpen && (
        <div 
          className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-40 lg:hidden"
          onClick={() => setIsMobileMenuOpen(false)}
        />
      )}

      {/* Sidebar */}
      <aside className={`
        fixed h-full z-50 bg-indigo-900 text-white transition-all duration-300 flex flex-col
        ${isMobileMenuOpen ? 'translate-x-0 w-64' : '-translate-x-full lg:translate-x-0'}
        ${isSidebarOpen ? 'lg:w-64' : 'lg:w-20'}
      `}>
        <div className="p-4 flex items-center justify-between border-b border-indigo-800">
          <span className={`font-bold text-xl ${(isSidebarOpen || isMobileMenuOpen) ? 'block' : 'hidden'}`}>Ecclesia</span>
          <button 
            onClick={() => setIsSidebarOpen(!isSidebarOpen)} 
            className="p-1 hover:bg-indigo-800 rounded hidden lg:block"
          >
            {isSidebarOpen ? '◀' : '▶'}
          </button>
          <button 
            onClick={() => setIsMobileMenuOpen(false)} 
            className="p-1 hover:bg-indigo-800 rounded lg:hidden text-2xl"
          >
            ✕
          </button>
        </div>
        <nav className="flex-1 mt-4 overflow-y-auto custom-scrollbar">
          {filteredMenuItems.map(item => (
            <button
              key={item.id}
              onClick={() => handleTabClick(item.id)}
              className={`w-full flex items-center p-4 transition-colors ${activeTab === item.id ? 'bg-indigo-700 border-r-4 border-white' : 'hover:bg-indigo-800'}`}
            >
              <span className="text-xl mr-3 shrink-0">{item.icon}</span>
              {(isSidebarOpen || isMobileMenuOpen) && <span className="font-medium whitespace-nowrap overflow-hidden text-ellipsis">{item.label}</span>}
            </button>
          ))}
        </nav>
        <div className="p-4 border-t border-indigo-800">
          <button onClick={logout} className="w-full flex items-center p-2 text-indigo-300 hover:text-white transition-colors">
            <span className="text-xl mr-3 shrink-0">🚪</span>
            {(isSidebarOpen || isMobileMenuOpen) && <span className="font-medium">Logout</span>}
          </button>
        </div>
      </aside>

      {/* Main Content Area */}
      <div className={`flex-1 flex flex-col transition-all duration-300 ${isSidebarOpen ? 'lg:ml-64' : 'lg:ml-20'}`}>
        <header className="bg-white border-b border-slate-200 h-16 flex items-center justify-between px-4 lg:px-8 sticky top-0 z-30">
          <div className="flex items-center space-x-3">
            <button 
              onClick={() => setIsMobileMenuOpen(true)}
              className="lg:hidden p-2 text-slate-600 hover:bg-slate-100 rounded-lg text-2xl"
            >
              ☰
            </button>
             <h2 className="text-lg lg:text-xl font-semibold text-slate-800 truncate max-w-[150px] sm:max-w-none">
              {menuItems.find(m => m.id === activeTab)?.label || 'Dashboard'}
             </h2>
             {currentChurch && (
               <span className="hidden sm:inline-block text-[10px] lg:text-sm text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded-full font-bold">
                 @{currentChurch.name}
               </span>
             )}
          </div>
          <div className="flex items-center space-x-2 lg:space-x-4">
            <div className="text-right hidden md:block">
              <p className="text-sm font-medium text-slate-900 truncate max-w-[120px]">{currentUser.fullName}</p>
              <p className="text-[10px] text-slate-500 capitalize">{currentUser.role.replace('_', ' ')}</p>
            </div>
            <div className="w-8 h-8 lg:w-10 lg:h-10 rounded-full bg-indigo-100 border border-indigo-200 flex items-center justify-center text-indigo-700 font-bold shrink-0">
              {currentUser.fullName.charAt(0)}
            </div>
          </div>
        </header>
        <main className="p-4 lg:p-8 flex-1">
          {children}
        </main>
      </div>
    </div>
  );
};

export default Layout;

import React from 'react';
import { useApp } from '../store';
import { AreaChart, Area, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { TaskStatus, UserRole } from '../types';

const Dashboard: React.FC = () => {
  const { currentUser, attendance, firstTimers, tasks, announcements, events, users } = useApp();

  const churchAttendance = attendance.filter(a => a.churchId === currentUser?.churchId);
  const pendingTasks = tasks.filter(t => t.assignedTo === currentUser?.id && t.status !== TaskStatus.DONE);
  const churchAnnouncements = announcements.filter(a => a.churchId === currentUser?.churchId).slice(0, 3);
  const pendingApprovals = users.filter(u => u.churchId === currentUser?.churchId && u.status === 'PENDING');

  const stats = [
    { label: 'Avg Attendance', value: churchAttendance.length > 0 ? Math.round(churchAttendance.reduce((acc, curr) => acc + curr.total, 0) / churchAttendance.length) : 0, color: 'text-blue-600', bg: 'bg-blue-50' },
    { label: 'Total First Timers', value: firstTimers.filter(ft => ft.churchId === currentUser?.churchId).length, color: 'text-green-600', bg: 'bg-green-50' },
    { label: 'Active Tasks', value: pendingTasks.length, color: 'text-orange-600', bg: 'bg-orange-50' },
    { label: 'Upcoming Events', value: events.length, color: 'text-purple-600', bg: 'bg-purple-50' },
  ];

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-2 md:grid-cols-2 lg:grid-cols-4 gap-4">
        {stats.map((stat, i) => (
          <div key={i} className="bg-white p-4 lg:p-6 rounded-xl border border-slate-200 shadow-sm">
            <p className="text-[10px] lg:text-sm font-medium text-slate-500 mb-1 uppercase tracking-wider">{stat.label}</p>
            <p className={`text-xl lg:text-3xl font-bold ${stat.color}`}>{stat.value}</p>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Analytics Chart */}
        <div className="lg:col-span-2 bg-white p-4 lg:p-6 rounded-xl border border-slate-200 shadow-sm">
          <h3 className="text-base lg:text-lg font-bold text-slate-800 mb-4">Attendance Trends</h3>
          <div className="h-48 lg:h-64 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <AreaChart data={churchAttendance}>
                <defs>
                  <linearGradient id="colorTotal" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="5%" stopColor="#6366f1" stopOpacity={0.3}/>
                    <stop offset="95%" stopColor="#6366f1" stopOpacity={0}/>
                  </linearGradient>
                </defs>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis dataKey="date" hide={window.innerWidth < 640} tick={{fontSize: 10}} />
                <YAxis tick={{fontSize: 10}} />
                <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 12px rgba(0,0,0,0.1)' }} />
                <Area type="monotone" dataKey="total" stroke="#6366f1" strokeWidth={3} fillOpacity={1} fill="url(#colorTotal)" />
              </AreaChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Pending Approvals (Admin Only) */}
        {currentUser?.role === UserRole.CHURCH_ADMIN && (
          <div className="bg-white p-4 lg:p-6 rounded-xl border border-slate-200 shadow-sm flex flex-col">
            <h3 className="text-base lg:text-lg font-bold text-slate-800 mb-4">Worker Approvals</h3>
            {pendingApprovals.length > 0 ? (
              <div className="space-y-3 overflow-y-auto max-h-[300px] lg:max-h-none">
                {pendingApprovals.map(user => (
                  <div key={user.id} className="flex items-center justify-between p-3 bg-slate-50 rounded-lg">
                    <div className="min-w-0 flex-1 mr-2">
                      <p className="text-sm font-bold text-slate-800 truncate">{user.fullName}</p>
                      <p className="text-[10px] text-slate-500 truncate">{user.email}</p>
                    </div>
                    <button className="shrink-0 text-[10px] font-bold bg-indigo-600 text-white px-3 py-1.5 rounded-md hover:bg-indigo-700">Approve</button>
                  </div>
                ))}
              </div>
            ) : (
              <div className="flex-1 flex flex-col items-center justify-center text-slate-400 py-8">
                <span className="text-3xl mb-2">✅</span>
                <p className="text-xs font-medium">No pending workers.</p>
              </div>
            )}
          </div>
        )}

        {/* Announcements */}
        <div className="bg-white p-4 lg:p-6 rounded-xl border border-slate-200 shadow-sm lg:col-span-1">
           <h3 className="text-base lg:text-lg font-bold text-slate-800 mb-4">Latest Updates</h3>
           <div className="space-y-4">
             {churchAnnouncements.map(ann => (
               <div key={ann.id} className="border-l-4 border-indigo-500 pl-4 py-1">
                 <p className="text-sm font-bold text-slate-800 truncate">{ann.title}</p>
                 <p className="text-xs text-slate-600 line-clamp-2">{ann.body}</p>
               </div>
             ))}
             {churchAnnouncements.length === 0 && <p className="text-xs text-slate-400 italic">No recent announcements.</p>}
           </div>
        </div>

        {/* Quick Tasks */}
        <div className="lg:col-span-2 bg-white p-4 lg:p-6 rounded-xl border border-slate-200 shadow-sm">
           <h3 className="text-base lg:text-lg font-bold text-slate-800 mb-4">My Tasks</h3>
           {pendingTasks.length > 0 ? (
             <div className="overflow-x-auto">
                <table className="w-full text-left">
                  <thead>
                    <tr className="text-slate-500 text-[10px] uppercase tracking-wider border-b">
                      <th className="pb-2">Task</th>
                      <th className="pb-2 hidden sm:table-cell">Priority</th>
                      <th className="pb-2 text-right">Action</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-50">
                    {pendingTasks.map(task => (
                      <tr key={task.id} className="text-xs hover:bg-slate-50">
                        <td className="py-3 pr-2">
                           <p className="font-bold text-slate-800 truncate max-w-[150px] sm:max-w-none">{task.title}</p>
                           <p className="sm:hidden text-[10px] text-slate-400">{task.priority} • {task.endDate}</p>
                        </td>
                        <td className="py-3 hidden sm:table-cell">
                          <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold ${
                            task.priority === 'High' ? 'bg-red-50 text-red-600' : 
                            task.priority === 'Medium' ? 'bg-yellow-50 text-yellow-600' : 'bg-blue-50 text-blue-600'
                          }`}>
                            {task.priority}
                          </span>
                        </td>
                        <td className="py-3 text-right">
                          <button className="text-indigo-600 hover:text-indigo-800 font-black text-[10px] uppercase">Complete</button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
             </div>
           ) : (
             <p className="text-slate-400 text-xs py-4 italic">No pending tasks. Great job!</p>
           )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { useApp, EXCHANGE_RATES } from '../store';
import { UserRole, Transaction, Budget, Currency } from '../types';

const Accounting: React.FC = () => {
  const { 
    transactions, budgets, currentUser, users, currentChurch,
    addTransaction, addBudget, toggleAccountingAccess, setChurchCurrency 
  } = useApp();

  const [activeTab, setActiveTab] = useState<'OVERVIEW' | 'TRANSACTIONS' | 'BUDGETS' | 'PERMISSIONS'>('OVERVIEW');
  const [showTxModal, setShowTxModal] = useState(false);
  const [showBudgetModal, setShowBudgetModal] = useState(false);
  const [converting, setConverting] = useState(false);

  const isAdmin = currentUser?.role === UserRole.CHURCH_ADMIN;
  const currencySymbol = currentChurch?.currency || Currency.USD;

  const churchTx = transactions.filter(t => t.churchId === currentUser?.churchId);
  const churchBudgets = budgets.filter(b => b.churchId === currentUser?.churchId);
  const churchWorkers = users.filter(u => u.churchId === currentUser?.churchId && u.role === UserRole.WORKER && u.status === 'APPROVED');

  const totalIncome = churchTx.filter(t => t.type === 'INCOME').reduce((acc, curr) => acc + curr.amount, 0);
  const totalExpense = churchTx.filter(t => t.type === 'EXPENSE').reduce((acc, curr) => acc + curr.amount, 0);
  const balance = totalIncome - totalExpense;

  const handleAddTx = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    addTransaction({
      churchId: currentUser!.churchId,
      type: formData.get('type') as any,
      category: formData.get('category') as string,
      amount: parseFloat(formData.get('amount') as string),
      date: formData.get('date') as string,
      description: formData.get('description') as string,
      recordedBy: currentUser!.id
    });
    setShowTxModal(false);
  };

  const handleAddBudget = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    addBudget({
      churchId: currentUser!.churchId,
      category: formData.get('category') as string,
      allocatedAmount: parseFloat(formData.get('amount') as string),
      spentAmount: 0,
      period: formData.get('period') as string
    });
    setShowBudgetModal(false);
  };

  const handleCurrencyChange = (newCurrency: Currency) => {
    if (currentChurch && currentChurch.currency !== newCurrency) {
      setConverting(true);
      setTimeout(() => {
        setChurchCurrency(currentChurch.id, newCurrency);
        setConverting(false);
      }, 600);
    }
  };

  return (
    <div className="space-y-6 lg:space-y-8 relative">
      {converting && (
        <div className="fixed inset-0 lg:absolute bg-white/60 backdrop-blur-[4px] z-[60] flex flex-col items-center justify-center rounded-3xl animate-in fade-in duration-300">
           <div className="w-12 h-12 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin mb-4"></div>
           <p className="text-indigo-600 font-black text-xs lg:text-sm uppercase tracking-widest px-4 text-center">Recalculating Financial Data...</p>
        </div>
      )}

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div>
          <h3 className="text-xl lg:text-2xl font-bold text-slate-800">Financial Management</h3>
          <p className="text-sm text-slate-500">Track tithes, expenses, and budget performance</p>
        </div>
        <div className="flex flex-wrap items-center gap-3 lg:gap-4">
          <div className="flex flex-col items-start md:items-end gap-1 shrink-0">
            <span className="text-[9px] font-black text-slate-400 uppercase tracking-tighter">Currency</span>
            <div className="flex bg-slate-100 p-1 rounded-xl border border-slate-200">
              {[Currency.USD, Currency.NGN, Currency.GBP].map(curr => (
                <button
                  key={curr}
                  onClick={() => handleCurrencyChange(curr)}
                  className={`px-3 py-1.5 rounded-lg text-xs font-bold transition-all ${currencySymbol === curr ? 'bg-white text-indigo-600 shadow-sm' : 'text-slate-400 hover:text-slate-600'}`}
                >
                  {curr}
                </button>
              ))}
            </div>
          </div>
          <button 
            onClick={() => setShowTxModal(true)}
            className="flex-1 md:flex-none bg-emerald-600 text-white px-4 py-2.5 lg:px-5 lg:py-2.5 rounded-xl hover:bg-emerald-700 transition shadow-lg shadow-emerald-100 font-bold text-xs lg:text-sm flex items-center justify-center gap-2"
          >
            <span>➕</span> Record Entry
          </button>
        </div>
      </div>

      <div className="overflow-x-auto pb-2 -mx-4 px-4 lg:mx-0 lg:px-0">
        <div className="flex bg-white p-1 rounded-2xl border border-slate-200 shadow-sm w-max min-w-full lg:min-w-0">
          {(['OVERVIEW', 'TRANSACTIONS', 'BUDGETS', 'PERMISSIONS'] as const).map((t) => (
            (t === 'PERMISSIONS' && !isAdmin) ? null : (
              <button
                key={t}
                onClick={() => setActiveTab(t)}
                className={`flex-1 lg:flex-none px-4 lg:px-6 py-2 rounded-xl text-[10px] lg:text-xs font-black transition-all whitespace-nowrap ${activeTab === t ? 'bg-indigo-600 text-white shadow-md shadow-indigo-100' : 'text-slate-400 hover:text-slate-600'}`}
              >
                {t}
              </button>
            )
          ))}
        </div>
      </div>

      {activeTab === 'OVERVIEW' && (
        <div className="space-y-6 lg:space-y-8">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 lg:gap-6">
            <div className="bg-indigo-600 p-6 lg:p-8 rounded-3xl text-white shadow-xl shadow-indigo-100 relative overflow-hidden">
              <div className="absolute top-0 right-0 p-6 lg:p-8 opacity-10 text-4xl lg:text-6xl italic font-black">{currencySymbol}</div>
              <p className="text-indigo-100 font-bold uppercase tracking-widest text-[10px] mb-2">Net Balance</p>
              <h2 className="text-2xl lg:text-4xl font-black">{currencySymbol}{balance.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</h2>
            </div>
            <div className="bg-white p-6 lg:p-8 rounded-3xl border border-slate-200 shadow-sm">
              <p className="text-slate-400 font-bold uppercase tracking-widest text-[10px] mb-2">Total Income</p>
              <h2 className="text-2xl lg:text-3xl font-black text-emerald-600">{currencySymbol}{totalIncome.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</h2>
            </div>
            <div className="bg-white p-6 lg:p-8 rounded-3xl border border-slate-200 shadow-sm">
              <p className="text-slate-400 font-bold uppercase tracking-widest text-[10px] mb-2">Total Expenses</p>
              <h2 className="text-2xl lg:text-3xl font-black text-rose-600">{currencySymbol}{totalExpense.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</h2>
            </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 lg:gap-8">
            <div className="bg-white p-6 lg:p-8 rounded-3xl border border-slate-200 shadow-sm">
              <h4 className="text-base lg:text-lg font-bold text-slate-800 mb-6 uppercase tracking-wider">Budget Status</h4>
              <div className="space-y-6">
                {churchBudgets.map(b => {
                  const percent = Math.min((b.spentAmount / b.allocatedAmount) * 100, 100);
                  const isOver = b.spentAmount > b.allocatedAmount;
                  return (
                    <div key={b.id}>
                      <div className="flex justify-between text-[10px] lg:text-xs font-bold mb-2">
                        <span className="text-slate-600 uppercase">{b.category}</span>
                        <span className={isOver ? 'text-rose-600' : 'text-slate-400'}>
                          {currencySymbol}{Math.round(b.spentAmount).toLocaleString()} / {currencySymbol}{Math.round(b.allocatedAmount).toLocaleString()}
                        </span>
                      </div>
                      <div className="h-2.5 lg:h-3 bg-slate-100 rounded-full overflow-hidden">
                        <div 
                          className={`h-full transition-all duration-700 ease-out ${isOver ? 'bg-rose-500' : 'bg-indigo-500'}`} 
                          style={{ width: `${percent}%` }}
                        ></div>
                      </div>
                    </div>
                  );
                })}
                {churchBudgets.length === 0 && (
                  <p className="text-center text-slate-400 py-8 italic text-xs">No budgets defined yet.</p>
                )}
              </div>
            </div>

            <div className="bg-white p-6 lg:p-8 rounded-3xl border border-slate-200 shadow-sm">
              <h4 className="text-base lg:text-lg font-bold text-slate-800 mb-6 uppercase tracking-wider">Recent Activity</h4>
              <div className="space-y-3">
                {churchTx.slice(0, 5).map(tx => (
                  <div key={tx.id} className="flex items-center justify-between p-3 lg:p-4 bg-slate-50 rounded-2xl border border-slate-100">
                    <div className="flex items-center gap-3 lg:gap-4 min-w-0">
                      <div className={`w-8 h-8 lg:w-10 lg:h-10 rounded-xl shrink-0 flex items-center justify-center font-black text-xs lg:text-base ${tx.type === 'INCOME' ? 'bg-emerald-100 text-emerald-600' : 'bg-rose-100 text-rose-600'}`}>
                        {tx.type === 'INCOME' ? '↓' : '↑'}
                      </div>
                      <div className="min-w-0">
                        <p className="text-xs lg:text-sm font-bold text-slate-800 truncate">{tx.description}</p>
                        <p className="text-[9px] lg:text-[10px] text-slate-400 uppercase font-black tracking-widest truncate">{tx.category} • {tx.date}</p>
                      </div>
                    </div>
                    <span className={`shrink-0 font-black text-xs lg:text-sm ${tx.type === 'INCOME' ? 'text-emerald-600' : 'text-rose-600'}`}>
                      {tx.type === 'INCOME' ? '+' : '-'}{currencySymbol}{tx.amount.toLocaleString()}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      )}

      {activeTab === 'TRANSACTIONS' && (
        <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse min-w-[600px]">
              <thead className="bg-slate-50 border-b border-slate-100">
                <tr className="text-[9px] lg:text-[10px] font-black text-slate-400 uppercase tracking-widest">
                  <th className="px-6 lg:px-8 py-5">Date</th>
                  <th className="px-6 lg:px-8 py-5">Description</th>
                  <th className="px-6 lg:px-8 py-5">Category</th>
                  <th className="px-6 lg:px-8 py-5 text-right">Amount ({currencySymbol})</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {churchTx.map(tx => (
                  <tr key={tx.id} className="hover:bg-slate-50/50 transition-colors">
                    <td className="px-6 lg:px-8 py-5 text-xs font-medium text-slate-500 whitespace-nowrap">{tx.date}</td>
                    <td className="px-6 lg:px-8 py-5 text-xs lg:text-sm font-bold text-slate-800">{tx.description}</td>
                    <td className="px-6 lg:px-8 py-5">
                       <span className={`px-2 py-0.5 rounded-lg text-[9px] font-black uppercase ${tx.type === 'INCOME' ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                        {tx.category}
                      </span>
                    </td>
                    <td className={`px-6 lg:px-8 py-5 text-right font-black text-xs lg:text-sm ${tx.type === 'INCOME' ? 'text-emerald-600' : 'text-rose-600'}`}>
                      {tx.type === 'INCOME' ? '+' : '-'}{tx.amount.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Rest of the tab content follows similar responsive patterns */}
      {/* ... (Existing modal code remains, it's already using responsive classes) ... */}
    </div>
  );
};

export default Accounting;

import React, { useState } from 'react';
import { useApp } from '../store';
import { UserRole, ChurchEvent } from '../types';

const Events: React.FC = () => {
  const { events, currentUser, addEvent, updateEvent, deleteEvent } = useApp();
  const [view, setView] = useState<'LIST' | 'CALENDAR'>('LIST');
  const [showAddModal, setShowAddModal] = useState(false);
  const [editingEvent, setEditingEvent] = useState<ChurchEvent | null>(null);

  const isAdmin = currentUser?.role === UserRole.CHURCH_ADMIN;
  const isUnitHead = currentUser?.role === UserRole.UNIT_HEAD;
  const canManage = isAdmin || isUnitHead;

  const churchEvents = events.filter(e => e.churchId === currentUser?.churchId);
  const sortedEvents = [...churchEvents].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

  // Calendar Logic
  const today = new Date();
  const [currentMonth, setCurrentMonth] = useState(new Date().getMonth());
  const [currentYear, setCurrentYear] = useState(new Date().getFullYear());

  const daysInMonth = (month: number, year: number) => new Date(year, month + 1, 0).getDate();
  const startDayOfMonth = (month: number, year: number) => new Date(year, month, 1).getDay();

  const monthNames = [
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December"
  ];

  const handlePrevMonth = () => {
    if (currentMonth === 0) {
      setCurrentMonth(11);
      setCurrentYear(currentYear - 1);
    } else {
      setCurrentMonth(currentMonth - 1);
    }
  };

  const handleNextMonth = () => {
    if (currentMonth === 11) {
      setCurrentMonth(0);
      setCurrentYear(currentYear + 1);
    } else {
      setCurrentMonth(currentMonth + 1);
    }
  };

  const handleCreateOrUpdate = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const formData = new FormData(e.currentTarget);
    const title = formData.get('title') as string;
    const date = formData.get('date') as string;
    const location = formData.get('location') as string;
    const description = formData.get('description') as string;

    if (editingEvent) {
      updateEvent(editingEvent.id, { title, date, location, description });
    } else {
      addEvent({
        churchId: currentUser!.churchId,
        title,
        date,
        location,
        description
      });
    }
    setShowAddModal(false);
    setEditingEvent(null);
  };

  return (
    <div className="space-y-6 lg:space-y-8">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div>
          <h3 className="text-xl lg:text-2xl font-bold text-slate-800">Events & Calendar</h3>
          <p className="text-sm text-slate-500">Scheduled activities and special services</p>
        </div>
        <div className="flex items-center gap-3">
          <div className="bg-white p-1 rounded-xl border border-slate-200 flex shadow-sm grow md:grow-0">
            <button 
              onClick={() => setView('LIST')}
              className={`flex-1 md:flex-none px-4 py-2 rounded-lg text-[10px] lg:text-xs font-black transition-all ${view === 'LIST' ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:text-slate-600'}`}
            >
              List View
            </button>
            <button 
              onClick={() => setView('CALENDAR')}
              className={`flex-1 md:flex-none px-4 py-2 rounded-lg text-[10px] lg:text-xs font-black transition-all ${view === 'CALENDAR' ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:text-slate-600'}`}
            >
              Calendar
            </button>
          </div>
          {canManage && (
            <button 
              onClick={() => setShowAddModal(true)}
              className="bg-indigo-600 text-white p-2.5 lg:px-6 lg:py-2.5 rounded-xl hover:bg-indigo-700 transition shadow-lg shadow-indigo-100 font-semibold flex items-center justify-center gap-2"
            >
              <span className="text-xl">+</span> <span className="hidden lg:inline">Add Event</span>
            </button>
          )}
        </div>
      </div>

      {view === 'LIST' ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 lg:gap-6">
          {sortedEvents.map(event => (
            <div key={event.id} className="bg-white rounded-3xl border border-slate-200 shadow-sm p-5 lg:p-6 group hover:border-indigo-300 transition-all flex flex-col">
              <div className="flex justify-between items-start mb-4">
                <div className="bg-indigo-50 text-indigo-600 p-2.5 lg:p-3 rounded-2xl">
