import React, { useState } from 'react';
import { useApp } from '../store';
import { FollowUpStatus, FirstTimer, UserRole } from '../types';
import { getFollowUpStrategy } from '../geminiService';

const FirstTimers: React.FC = () => {
  const { firstTimers, currentUser, addFirstTimer, updateFirstTimer } = useApp();
  const [showAddModal, setShowAddModal] = useState(false);
  const [editingFT, setEditingFT] = useState<FirstTimer | null>(null);
  const [strategyLoading, setStrategyLoading] = useState<string | null>(null);
  const [strategyContent, setStrategyContent] = useState<string | null>(null);

  const churchFTs = firstTimers.filter(ft => ft.churchId === currentUser?.churchId);

  // Permission check: Only Pastor (CHURCH_ADMIN) and Unit Head (UNIT_HEAD) can add visitors
  const canAddVisitor = currentUser?.role === UserRole.CHURCH_ADMIN || currentUser?.role === UserRole.UNIT_HEAD;

  const handleAISuggestion = async (ft: FirstTimer) => {
    setStrategyLoading(ft.id);
    setStrategyContent(null);
    const strategy = await getFollowUpStrategy(ft.notes, ft.fullName);
    setStrategyContent(strategy);
    setStrategyLoading(null);
    window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
  };

  const handleStatusUpdate = (ft: FirstTimer, newStatus: FollowUpStatus) => {
    updateFirstTimer(ft.id, { status: newStatus });
  };

  const handleFollowUpSave = (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    if (!editingFT) return;

    const formData = new FormData(e.currentTarget);
    const newStatus = formData.get('status') as FollowUpStatus;
    const newNote = formData.get('notes') as string;

    updateFirstTimer(editingFT.id, { 
      status: newStatus,
      notes: newNote
    });

    setEditingFT(null);
  };

  return (
    <div className="space-y-6 lg:space-y-8">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div>
          <h3 className="text-xl lg:text-2xl font-bold text-slate-800">Visitor Tracking</h3>
          <p className="text-sm text-slate-500">Manage first-time guests and follow-up activities</p>
        </div>
        {canAddVisitor && (
          <button 
            onClick={() => setShowAddModal(true)}
            className="w-full sm:w-auto bg-indigo-600 text-white px-6 py-2.5 rounded-xl hover:bg-indigo-700 transition shadow-lg shadow-indigo-100 font-bold text-sm flex items-center justify-center gap-2"
          >
            <span className="text-xl">+</span> Add Visitor
          </button>
        )}
      </div>

      <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left min-w-[700px]">
            <thead className="bg-slate-50 border-b border-slate-100">
              <tr className="text-slate-400 text-[10px] uppercase tracking-widest font-black">
                <th className="px-6 lg:px-8 py-5">Visitor Details</th>
                <th className="px-6 lg:px-8 py-5">Visit Date</th>
                <th className="px-6 lg:px-8 py-5">Assigned Follow-up</th>
                <th className="px-6 lg:px-8 py-5">Status</th>
                <th className="px-6 lg:px-8 py-5 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {churchFTs.map(ft => (
                <tr key={ft.id} className="hover:bg-slate-50/50 transition-colors">
                  <td className="px-6 lg:px-8 py-5">
                    <div className="font-bold text-slate-800 text-sm lg:text-base">{ft.fullName}</div>
                    <div className="text-[10px] lg:text-xs text-slate-500 font-medium">{ft.phone}</div>
                  </td>
                  <td className="px-6 lg:px-8 py-5 text-xs lg:text-sm text-slate-600 font-medium whitespace-nowrap">
                    {ft.dateVisited}
                  </td>
                  <td className="px-6 lg:px-8 py-5">
                    <div className="text-xs font-bold text-indigo-600 bg-indigo-50 px-3 py-1 rounded-lg inline-block whitespace-nowrap">
                      {ft.assignedTo ? '👤 Follow-up Assigned' : '⏳ Pending Assignment'}
                    </div>
                  </td>
                  <td className="px-6 lg:px-8 py-5">
                    <select 
                      value={ft.status}
                      onChange={(e) => handleStatusUpdate(ft, e.target.value as FollowUpStatus)}
                      className={`px-3 py-1 rounded-full text-[9px] lg:text-[10px] font-black uppercase tracking-tight whitespace-nowrap outline-none border-none cursor-pointer appearance-none text-center transition-colors ${
                        ft.status === FollowUpStatus.CONVERTED ? 'bg-emerald-100 text-emerald-700' :
                        ft.status === FollowUpStatus.NEEDS_FOLLOW_UP ? 'bg-rose-100 text-rose-700' : 
                        ft.status === FollowUpStatus.CONTACTED ? 'bg-blue-100 text-blue-700' :
                        'bg-slate-100 text-slate-600'
                      }`}
                    >
                      {Object.values(FollowUpStatus).map(status => (
                        <option key={status} value={status} className="bg-white text-slate-800 normal-case font-medium">
                          {status}
                        </option>
                      ))}
                    </select>
                  </td>
                  <td className="px-6 lg:px-8 py-5 text-right">
                    <div className="flex justify-end items-center gap-3">
                      <button 
                        onClick={() => handleAISuggestion(ft)}
                        disabled={strategyLoading === ft.id}
                        className={`text-[10px] lg:text-xs font-black uppercase tracking-widest px-3 py-1.5 rounded-lg transition-all ${
                          strategyLoading === ft.id 
                          ? 'bg-slate-100 text-slate-400' 
                          : 'bg-indigo-50 text-indigo-600 hover:bg-indigo-100'
                        }`}
                      >
                        {strategyLoading === ft.id ? 'Analyzing...' : '✨ AI Strategy'}
                      </button>
                      <button 
                        onClick={() => setEditingFT(ft)}
                        className="text-slate-400 hover:text-slate-600 p-2 rounded-lg hover:bg-slate-100 transition-colors"
                      >
                        ✏️
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
              {churchFTs.length === 0 && (
                <tr>
                  <td colSpan={5} className="p-20 text-center">
                    <div className="flex flex-col items-center">
                       <span className="text-4xl mb-4 opacity-50">👋</span>
                       <p className="text-slate-400 font-bold text-sm uppercase tracking-widest">No visitors recorded yet</p>
                       <p className="text-xs text-slate-400 mt-1">Add your first guest to start tracking growth.</p>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {strategyContent && (
        <div id="ai-advice" className="bg-slate-900 text-white p-6 lg:p-8 rounded-3xl shadow-2xl animate-in slide-in-from-bottom-8 duration-500 relative overflow-hidden group">
          <div className="absolute top-0 right-0 p-8 opacity-10 text-6xl group-hover:scale-110 transition-transform duration-700">✨</div>
          <div className="relative z-10">
            <div className="flex justify-between items-start mb-6">
              <div>
                <h4 className="text-xl lg:text-2xl font-black mb-1">AI Follow-up Advisor</h4>
                <p className="text-xs text-indigo-300 font-bold uppercase tracking-widest">Customized Engagement Strategy</p>
              </div>
              <button 
                onClick={() => setStrategyContent(null)} 
                className="bg-white/10 hover:bg-white/20 p-2 rounded-xl transition-colors"
              >
                ✕
              </button>
            </div>
            <div className="bg-white/5 backdrop-blur-sm border border-white/10 p-6 rounded-2xl text-sm lg:text-base leading-relaxed text-slate-200">
              {strategyContent}
            </div>
          </div>
        </div>
      )}

      {/* Edit Follow-up Modal */}
      {editingFT && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-[60] p-4">
          <div className="bg-white rounded-3xl w-full max-w-lg p-6 lg:p-10 shadow-2xl animate-in zoom-in-95 duration-200">
            <div className="flex justify-between items-center mb-8">
              <h2 className="text-2xl font-black text-slate-800 tracking-tight">Update Follow-up</h2>
              <button 
                onClick={() => setEditingFT(null)} 
                className="text-slate-400 hover:text-slate-600 text-xl"
