            </div>

            <form onSubmit={handleFollowUpSave} className="space-y-5">
              <div>
                <p className="text-xs font-black text-slate-400 uppercase tracking-widest mb-1">Guest</p>
                <p className="text-lg font-bold text-slate-800">{editingFT.fullName}</p>
              </div>

              <div>
                <label className="block text-xs font-black text-slate-500 uppercase tracking-widest mb-2">Engagement Status</label>
                <select 
                  name="status" 
                  defaultValue={editingFT.status}
                  className="w-full border-slate-200 rounded-2xl p-4 focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 focus:outline-none border bg-slate-50 text-sm font-bold"
                >
                  {Object.values(FollowUpStatus).map(status => (
                    <option key={status} value={status}>{status}</option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-xs font-black text-slate-500 uppercase tracking-widest mb-2">Follow-up Notes / Progress</label>
                <textarea 
                  name="notes" 
                  defaultValue={editingFT.notes}
