          <div className="bg-white rounded-3xl w-full max-w-lg p-6 lg:p-10 shadow-2xl animate-in zoom-in-95 duration-200 max-h-[90vh] overflow-y-auto custom-scrollbar">
            <div className="flex justify-between items-center mb-8">
              <h2 className="text-2xl lg:text-3xl font-black text-slate-800 tracking-tight">Guest Registration</h2>
