                {currencySymbol}{balance.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
              </h2>
            </div>
            <div className="bg-white p-8 lg:p-10 rounded-[3rem] border border-slate-200 shadow-sm relative overflow-hidden">
              <p className="text-emerald-500 font-black uppercase tracking-[0.2em] text-[10px] mb-4">Total Income</p>
              <h2 className="text-2xl lg:text-4xl font-black text-emerald-600 tracking-tighter truncate">+{currencySymbol}{totalIncome.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</h2>
              <div className="absolute bottom-0 right-0 p-6 opacity-5 text-6xl">📈</div>
            </div>
            <div className="bg-white p-8 lg:p-10 rounded-[3rem] border border-slate-200 shadow-sm relative overflow-hidden">
              <p className="text-rose-500 font-black uppercase tracking-[0.2em] text-[10px] mb-4">Total Expenses</p>
              <h2 className="text-2xl lg:text-4xl font-black text-rose-600 tracking-tighter truncate">-{currencySymbol}{totalExpense.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</h2>
              <div className="absolute bottom-0 right-0 p-6 opacity-5 text-6xl">📉</div>
            </div>
