export default Login;

export enum UserRole {
  PLATFORM_OWNER = 'PLATFORM_OWNER',
  CHURCH_ADMIN = 'CHURCH_ADMIN',
  UNIT_HEAD = 'UNIT_HEAD',
  WORKER = 'WORKER'
}

export enum Currency {
  USD = '$',
  NGN = '₦',
  GBP = '£'
}

export enum FollowUpStatus {
  NEEDS_FOLLOW_UP = 'Needs Follow-up',
  CONTACTED = 'Contacted',
  SCHEDULED = 'Follow-up Scheduled',
  JOINED_UNIT = 'Joined a Unit',
  NOT_INTERESTED = 'Not Interested',
  NO_RESPONSE = 'No Response',
  CONVERTED = 'Converted to Member'
}

export enum TaskStatus {
  IN_PROGRESS = 'In Progress',
  DONE = 'Done',
  SUSPENDED = 'Suspended'
}

export enum Priority {
  HIGH = 'High',
  MEDIUM = 'Medium',
  LOW = 'Low'
}

export interface Church {
  id: string;
  name: string;
  city: string;
  state: string;
  country: string;
  phone: string;
  location: string; // Concatenated legacy field
  adminId: string;
  createdAt: string;
  currency?: Currency;
}

export interface User {
  id: string;
  churchId: string;
  fullName: string;
  email: string;
  role: UserRole;
  unitId?: string;
  status: 'PENDING' | 'APPROVED';
  dateOfBirth?: string;
  anniversaryDate?: string;
  hasAccountingAccess?: boolean;
}

export interface Unit {
  id: string;
  churchId: string;
  name: string;
  headIds: string[];
}

export interface FirstTimer {
  id: string;
  churchId: string;
  fullName: string;
  phone: string;
  email?: string;
  dateVisited: string;
  invitedBy?: string;
  assignedTo?: string; // Worker ID
  status: FollowUpStatus;
  notes: string;
  history: FollowUpLog[];
}

export interface FollowUpLog {
  id: string;
  date: string;
  action: string;
  performedBy: string;
}

export interface ActionPlan {
  id: string;
  churchId: string;
  unitId: string;
  title: string;
  description: string;
  startDate: string;
  endDate: string;
  assignedTo: string; // User ID
  priority: Priority;
  status: TaskStatus;
}

export interface AttendanceRecord {
  id: string;
  churchId: string;
  date: string;
  total: number;
  male: number;
  female: number;
  children: number;
}

export interface Announcement {
  id: string;
  churchId: string;
  unitId?: string; // If null, it's global for church
  title: string;
  body: string;
  expiryDate?: string;
  createdAt: string;
}

export interface Property {
  id: string;
  churchId: string;
  unitId: string;
  name: string;
  quantity: number;
  status: 'Functional' | 'Maintenance' | 'Damaged';
}

export interface ChurchEvent {
  id: string;
  churchId: string;
  title: string;
  description: string;
  date: string;
  location: string;
}

export interface Transaction {
  id: string;
  churchId: string;
  type: 'INCOME' | 'EXPENSE';
  category: string;
  amount: number;
  date: string;
  description: string;
  recordedBy: string;
}

export interface Budget {
  id: string;
  churchId: string;
  category: string;
  allocatedAmount: number;
  spentAmount: number;
  period: string; // e.g., "Monthly - May 2024"
}

import React, { createContext, useContext, useState, useEffect, ReactNode } from 'react';
import { 
  User, Church, Unit, FirstTimer, AttendanceRecord, ActionPlan, 
  Announcement, Property, ChurchEvent, UserRole, Transaction, Budget, Currency 
} from './types';
import * as Mocks from './mockData';

export const EXCHANGE_RATES: Record<Currency, number> = {
  [Currency.USD]: 1,
  [Currency.NGN]: 1500,
  [Currency.GBP]: 0.78
};

interface AppState {
  currentUser: User | null;
  currentChurch: Church | null;
  churches: Church[];
  users: User[];
  units: Unit[];
  firstTimers: FirstTimer[];
  attendance: AttendanceRecord[];
  tasks: ActionPlan[];
  announcements: Announcement[];
  properties: Property[];
  events: ChurchEvent[];
  transactions: Transaction[];
  budgets: Budget[];
}

interface AppContextProps extends AppState {
  login: (email: string) => void;
  logout: () => void;
  registerUser: (user: Omit<User, 'id'>) => User;
  addChurch: (church: Omit<Church, 'id' | 'createdAt' | 'location'>) => Church;
  setCurrentChurchId: (id: string) => void;
  updateUser: (user: Partial<User>) => void;
  approveUser: (userId: string) => void;
  addFirstTimer: (ft: Omit<FirstTimer, 'id'>) => void;
  updateFirstTimer: (id: string, updates: Partial<FirstTimer>) => void;
  addAttendance: (record: Omit<AttendanceRecord, 'id'>) => void;
  addTask: (task: Omit<ActionPlan, 'id'>) => void;
  updateTask: (id: string, status: any) => void;
  addUnit: (unit: Omit<Unit, 'id'>) => void;
  updateUnit: (id: string, updates: Partial<Unit>) => void;
  deleteUnit: (id: string) => void;
  addProperty: (prop: Omit<Property, 'id'>) => void;
  updateProperty: (id: string, updates: Partial<Property>) => void;
  deleteProperty: (id: string) => void;
  addAnnouncement: (ann: Omit<Announcement, 'id' | 'createdAt'>) => void;
  updateAnnouncement: (id: string, updates: Partial<Announcement>) => void;
  deleteAnnouncement: (id: string) => void;
  addEvent: (event: Omit<ChurchEvent, 'id'>) => void;
  updateEvent: (id: string, updates: Partial<ChurchEvent>) => void;
  deleteEvent: (id: string) => void;
  addTransaction: (tx: Omit<Transaction, 'id'>) => void;
  addBudget: (b: Omit<Budget, 'id'>) => void;
  toggleAccountingAccess: (userId: string) => void;
  setChurchCurrency: (churchId: string, currency: Currency) => void;
}

const AppContext = createContext<AppContextProps | undefined>(undefined);

export const AppProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [state, setState] = useState<AppState>(() => {
    const saved = localStorage.getItem('ecclesia_state');
    if (saved) return JSON.parse(saved);
    return {
      currentUser: null,
      currentChurch: null,
      churches: Mocks.MOCK_CHURCHES.map(c => ({ 
        ...c, 
        currency: Currency.USD,
        city: c.location.split(', ')[0] || '',
        state: c.location.split(', ')[1] || '',
        country: 'Nigeria', // Mock default
        phone: '+234 000 000 0000' // Mock default
      })),
      users: Mocks.MOCK_USERS as any,
      units: Mocks.MOCK_UNITS,
      firstTimers: Mocks.MOCK_FIRST_TIMERS as any,
      attendance: Mocks.MOCK_ATTENDANCE,
      tasks: Mocks.MOCK_TASKS as any,
      announcements: Mocks.MOCK_ANNOUNCEMENTS as any,
      properties: Mocks.MOCK_PROPERTIES as any,
      events: Mocks.MOCK_EVENTS as any,
      transactions: [],
      budgets: [],
    };
  });

  useEffect(() => {
    localStorage.setItem('ecclesia_state', JSON.stringify(state));
  }, [state]);

  const login = (email: string) => {
    const user = state.users.find(u => u.email.toLowerCase() === email.toLowerCase());
    if (user) {
      const church = state.churches.find(c => c.id === user.churchId) || null;
      setState(prev => ({ ...prev, currentUser: user, currentChurch: church }));
    }
  };

  const logout = () => {
    setState(prev => ({ ...prev, currentUser: null, currentChurch: null }));
  };

  const addChurch = (churchData: Omit<Church, 'id' | 'createdAt' | 'location'>) => {
    const newChurch: Church = {
      ...churchData,
      id: 'c-' + Math.random().toString(36).substr(2, 9),
      createdAt: new Date().toISOString().split('T')[0],
      location: `${churchData.city}, ${churchData.state}`,
      currency: Currency.USD
    };
    setState(prev => ({
      ...prev,
      churches: [...prev.churches, newChurch]
    }));
    return newChurch;
  };

  const registerUser = (userData: Omit<User, 'id'>) => {
    const newUser: User = {
      ...userData,
      id: 'u-' + Math.random().toString(36).substr(2, 9),
    };
    setState(prev => ({
      ...prev,
      users: [...prev.users, newUser]
    }));
    return newUser;
  };

  const setCurrentChurchId = (id: string) => {
     const church = state.churches.find(c => c.id === id) || null;
     setState(prev => ({ ...prev, currentChurch: church }));
  }

  const approveUser = (userId: string) => {
    setState(prev => ({
      ...prev,
      users: prev.users.map(u => u.id === userId ? { ...u, status: 'APPROVED' } : u)
    }));
  };

  const addFirstTimer = (ft: Omit<FirstTimer, 'id'>) => {
    const newFT = { ...ft, id: Math.random().toString(36).substr(2, 9) };
    setState(prev => ({ ...prev, firstTimers: [newFT as any, ...prev.firstTimers] }));
  };

  const updateFirstTimer = (id: string, updates: Partial<FirstTimer>) => {
    setState(prev => ({
      ...prev,
      firstTimers: prev.firstTimers.map(f => f.id === id ? { ...f, ...updates } : f)
    }));
  };

  const addAttendance = (record: Omit<AttendanceRecord, 'id'>) => {
    const newRecord = { ...record, id: Math.random().toString(36).substr(2, 9) };
    setState(prev => ({ ...prev, attendance: [newRecord as any, ...prev.attendance] }));
  };

  const addTask = (task: Omit<ActionPlan, 'id'>) => {
    const newTask = { ...task, id: Math.random().toString(36).substr(2, 9) };
    setState(prev => ({ ...prev, tasks: [newTask as any, ...prev.tasks] }));
  };

  const updateTask = (id: string, status: any) => {
    setState(prev => ({
      ...prev,
      tasks: prev.tasks.map(t => t.id === id ? { ...t, status } : t)
    }));
  }

  const addUnit = (unit: Omit<Unit, 'id'>) => {
    const newUnit = { ...unit, id: Math.random().toString(36).substr(2, 9) };
    setState(prev => ({ ...prev, units: [...prev.units, newUnit] }));
  };

  const updateUnit = (id: string, updates: Partial<Unit>) => {
    setState(prev => ({
      ...prev,
      units: prev.units.map(u => u.id === id ? { ...u, ...updates } : u)
    }));
  };

  const deleteUnit = (id: string) => {
    setState(prev => ({
      ...prev,
      units: prev.units.filter(u => u.id !== id)
    }));
  };

  const addProperty = (prop: Omit<Property, 'id'>) => {
    const newProp = { ...prop, id: Math.random().toString(36).substr(2, 9) };
    setState(prev => ({ ...prev, properties: [...prev.properties, newProp as any] }));
  };

  const updateProperty = (id: string, updates: Partial<Property>) => {
    setState(prev => ({
      ...prev,
      properties: prev.properties.map(p => p.id === id ? { ...p, ...updates } : p)
    }));
  };

  const deleteProperty = (id: string) => {
    setState(prev => ({
      ...prev,
      properties: prev.properties.filter(p => p.id !== id)
    }));
  };

  const addAnnouncement = (ann: Omit<Announcement, 'id' | 'createdAt'>) => {
    const newAnn = { 
      ...ann, 
      id: Math.random().toString(36).substr(2, 9),
      createdAt: new Date().toISOString().split('T')[0]
    };
    setState(prev => ({ ...prev, announcements: [newAnn as any, ...prev.announcements] }));
  };

  const updateAnnouncement = (id: string, updates: Partial<Announcement>) => {
    setState(prev => ({
      ...prev,
      announcements: prev.announcements.map(a => a.id === id ? { ...a, ...updates } : a)
    }));
  };

  const deleteAnnouncement = (id: string) => {
    setState(prev => ({
      ...prev,
      announcements: prev.announcements.filter(a => a.id !== id)
    }));
  };

  const addEvent = (event: Omit<ChurchEvent, 'id'>) => {
    const newEvent = { 
      ...event, 
      id: Math.random().toString(36).substr(2, 9) 
    };
    setState(prev => ({ ...prev, events: [newEvent as any, ...prev.events] }));
  };

  const updateEvent = (id: string, updates: Partial<ChurchEvent>) => {
    setState(prev => ({
      ...prev,
      events: prev.events.map(e => e.id === id ? { ...e, ...updates } : e)
    }));
  };

  const deleteEvent = (id: string) => {
    setState(prev => ({
      ...prev,
      events: prev.events.filter(e => e.id !== id)
    }));
  };

  const addTransaction = (tx: Omit<Transaction, 'id'>) => {
    const newTx = { ...tx, id: Math.random().toString(36).substr(2, 9) };
    setState(prev => ({ 
      ...prev, 
      transactions: [newTx as any, ...prev.transactions],
      budgets: tx.type === 'EXPENSE' 
        ? prev.budgets.map(b => b.category === tx.category ? { ...b, spentAmount: b.spentAmount + tx.amount } : b)
        : prev.budgets
    }));
  };

  const addBudget = (b: Omit<Budget, 'id'>) => {
    const newB = { ...b, id: Math.random().toString(36).substr(2, 9) };
    setState(prev => ({ ...prev, budgets: [...prev.budgets, newB as any] }));
  };

  const toggleAccountingAccess = (userId: string) => {
    setState(prev => ({
      ...prev,
      users: prev.users.map(u => u.id === userId ? { ...u, hasAccountingAccess: !u.hasAccountingAccess } : u)
    }));
  };

  const setChurchCurrency = (churchId: string, targetCurrency: Currency) => {
    setState(prev => {
      const church = prev.churches.find(c => c.id === churchId);
      if (!church) return prev;

      const sourceCurrency = church.currency || Currency.USD;
      if (sourceCurrency === targetCurrency) return prev;

      const conversionFactor = EXCHANGE_RATES[targetCurrency] / EXCHANGE_RATES[sourceCurrency];

      const updatedChurches = prev.churches.map(c => c.id === churchId ? { ...c, currency: targetCurrency } : c);
      const updatedCurrentChurch = prev.currentChurch?.id === churchId ? { ...prev.currentChurch, currency: targetCurrency } : prev.currentChurch;

      const updatedTransactions = prev.transactions.map(tx => 
        tx.churchId === churchId ? { ...tx, amount: Number((tx.amount * conversionFactor).toFixed(2)) } : tx
      );

      const updatedBudgets = prev.budgets.map(b => 
        b.churchId === churchId ? { 
          ...b, 
          allocatedAmount: Number((b.allocatedAmount * conversionFactor).toFixed(2)),
          spentAmount: Number((b.spentAmount * conversionFactor).toFixed(2))
        } : b
      );

      return {
        ...prev,
        churches: updatedChurches,
        currentChurch: updatedCurrentChurch,
        transactions: updatedTransactions,
        budgets: updatedBudgets
      };
    });
  };

  const updateUser = (user: Partial<User>) => {};

  return (
    <AppContext.Provider value={{ 
      ...state, 
      login, 
      logout, 
      registerUser,
      addChurch,
      setCurrentChurchId, 
      updateUser, 
      approveUser, 
      addFirstTimer, 
      updateFirstTimer, 
      addAttendance,
      addTask,
      updateTask,
      addUnit,
      updateUnit,
      deleteUnit,
      addProperty,
      updateProperty,
      deleteProperty,
      addAnnouncement,
      updateAnnouncement,
      deleteAnnouncement,
      addEvent,
      updateEvent,
      deleteEvent,
      addTransaction,
      addBudget,
      toggleAccountingAccess,
      setChurchCurrency
    }}>
      {children}
    </AppContext.Provider>
  );
};

export const useApp = () => {
  const context = useContext(AppContext);
  if (!context) throw new Error('useApp must be used within an AppProvider');
  return context;
};

import React, { useState, useEffect } from 'react';
import { useApp } from '../store';
import { UserRole } from '../types';

const Login: React.FC = () => {
  const { login, registerUser, addChurch, churches, units } = useApp();
  const [isSignup, setIsSignup] = useState(false);
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);

  // Secret access state
  const [isSecretVisible, setIsSecretVisible] = useState(false);

  // Signup State (Strictly Church Admin)
  const [fullName, setFullName] = useState('');
  const [churchPhone, setChurchPhone] = useState('');
  const [churchCity, setChurchCity] = useState('');
  const [churchState, setChurchState] = useState('');
  const [churchCountry, setChurchCountry] = useState('');
  const [newChurchName, setNewChurchName] = useState('');

  // Verification State
  const [isVerifying, setIsVerifying] = useState(false);
  const [verificationCode, setVerificationCode] = useState('');
  const [isGoogleLoading, setIsGoogleLoading] = useState(false);
  const [resendTimer, setResendTimer] = useState(0);

  // Check for secret hash on mount and hash change
  useEffect(() => {
    const checkHash = () => {
      if (window.location.hash === '#platform-vault') {
        setIsSecretVisible(true);
      } else {
        setIsSecretVisible(false);
      }
    };

    checkHash();
    window.addEventListener('hashchange', checkHash);
    return () => window.removeEventListener('hashchange', checkHash);
  }, []);

  useEffect(() => {
    let interval: any;
    if (resendTimer > 0) {
      interval = setInterval(() => setResendTimer(prev => prev - 1), 1000);
    }
    return () => clearInterval(interval);
  }, [resendTimer]);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    login(email);
  };

  const startVerification = (e: React.FormEvent) => {
    e.preventDefault();
    setIsVerifying(true);
    setResendTimer(60);
  };

  const handleGoogleAuth = () => {
    setIsGoogleLoading(true);
    setTimeout(() => {
      setIsGoogleLoading(false);
      setIsSignup(true);
      setEmail('verified.google.user@gmail.com');
      setFullName('Google User');
      setIsVerifying(false); 
    }, 1500);
  };

  const handleCompleteSignup = (e: React.FormEvent) => {
    e.preventDefault();
    if (verificationCode !== '123456' && !email.includes('google')) {
      alert("Invalid verification code. Please use 123456 for this demo.");
      return;
    }

    // New church creation with expanded fields
    const church = addChurch({
      name: newChurchName,
      city: churchCity,
      state: churchState,
      country: churchCountry,
      phone: churchPhone,
      adminId: 'pending',
    });

    registerUser({
      churchId: church.id,
      fullName,
      email,
      role: UserRole.CHURCH_ADMIN,
      status: 'APPROVED'
    });

    login(email);
  };

  if (isVerifying) {
    return (
      <div className="min-h-screen bg-indigo-50 flex items-center justify-center p-4">
        <div className="bg-white rounded-[2.5rem] shadow-2xl w-full max-w-md p-8 lg:p-12 animate-in zoom-in-95 duration-300">
          <div className="text-center mb-8">
            <div className="w-20 h-20 bg-indigo-100 rounded-full flex items-center justify-center mx-auto mb-6">
              <span className="text-4xl">📧</span>
            </div>
            <h2 className="text-2xl font-black text-slate-800 mb-2">Verify your email</h2>
            <p className="text-sm text-slate-500">
              We've sent a code to <span className="font-bold text-indigo-600">{email}</span>. 
              Enter it below to continue.
            </p>
          </div>

          <form onSubmit={handleCompleteSignup} className="space-y-6">
            <div>
              <label className="block text-[10px] font-black text-slate-400 mb-2 uppercase tracking-widest text-center">6-Digit Verification Code</label>
              <input 
                required
                type="text" 
                maxLength={6}
                value={verificationCode}
                onChange={(e) => setVerificationCode(e.target.value.replace(/\D/g, ''))}
                placeholder="0 0 0 0 0 0"
                className="w-full px-6 py-4 bg-slate-50 border-2 border-slate-100 rounded-2xl focus:border-indigo-500 focus:outline-none transition-all text-3xl font-black text-center tracking-[0.5em]"
              />
              <p className="text-center text-[10px] text-slate-400 mt-2 italic">Tip: Use 123456 for the demo</p>
            </div>

            <button 
              type="submit"
              className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl hover:bg-indigo-700 shadow-xl shadow-indigo-100 transition-all text-sm uppercase tracking-widest"
            >
              Verify & Create Account
            </button>

            <div className="text-center">
              <button 
                type="button"
                disabled={resendTimer > 0}
                onClick={() => setResendTimer(60)}
                className={`text-xs font-black uppercase tracking-widest transition-colors ${resendTimer > 0 ? 'text-slate-300' : 'text-indigo-600 hover:text-indigo-800'}`}
              >
                {resendTimer > 0 ? `Resend code in ${resendTimer}s` : 'Resend Code'}
              </button>
            </div>

            <button 
              type="button"
              onClick={() => setIsVerifying(false)}
              className="w-full text-xs font-bold text-slate-400 hover:text-slate-600 uppercase tracking-widest transition-colors"
            >
              ← Back to Details
            </button>
          </form>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-indigo-50 flex items-center justify-center p-4 lg:p-12 overflow-y-auto">
      <div className="bg-white rounded-[2rem] lg:rounded-[3rem] shadow-2xl w-full max-w-2xl overflow-hidden flex flex-col my-8">
        <div className="bg-indigo-900 p-8 lg:p-12 text-center text-white relative">
          <div className="absolute top-4 left-1/2 -translate-x-1/2 w-12 h-1.5 bg-white/20 rounded-full lg:hidden"></div>
          <h1 className="text-3xl lg:text-5xl font-black mb-2 tracking-tighter">Ecclesia</h1>
          <p className="text-indigo-200 text-sm lg:text-base opacity-80 uppercase tracking-widest font-bold">
            {isSignup ? 'Create Church Account' : 'Church Management System'}
          </p>
        </div>

        <div className="p-8 lg:p-12">
          {/* Third Party Auth */}
          <div className="mb-8">
            <button 
              onClick={handleGoogleAuth}
              disabled={isGoogleLoading}
              className="w-full flex items-center justify-center gap-3 py-4 border-2 border-slate-100 rounded-2xl font-bold text-slate-600 hover:bg-slate-50 transition-all relative"
            >
              {isGoogleLoading ? (
                <div className="w-5 h-5 border-2 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
              ) : (
                <>
                  <svg width="20" height="20" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" fill="#4285F4"/>
                    <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853"/>
                    <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l3.66-2.84z" fill="#FBBC05"/>
                    <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335"/>
                  </svg>
                  <span>Continue with Google</span>
                </>
              )}
            </button>
            <div className="relative mt-8 mb-4">
              <div className="absolute inset-0 flex items-center"><div className="w-full border-t border-slate-100"></div></div>
              <div className="relative flex justify-center text-[10px] font-black uppercase tracking-widest"><span className="bg-white px-4 text-slate-300">Or use email</span></div>
            </div>
          </div>

          {isSignup ? (
            <form onSubmit={startVerification} className="space-y-5 animate-in fade-in slide-in-from-bottom-4 duration-500">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                <div className="md:col-span-1">
                  <label className="block text-[10px] font-black text-slate-400 mb-1.5 uppercase tracking-widest">Admin Full Name</label>
                  <input 
                    required
                    type="text" 
                    value={fullName}
                    onChange={(e) => setFullName(e.target.value)}
                    placeholder="Pastor John Doe"
                    className="w-full px-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/5 focus:outline-none transition-all text-sm font-bold"
                  />
                </div>
                <div className="md:col-span-1">
                  <label className="block text-[10px] font-black text-slate-400 mb-1.5 uppercase tracking-widest">Admin Email</label>
                  <input 
                    required
                    type="email" 
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    placeholder="admin@church.com"
                    className="w-full px-5 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl focus:border-indigo-500 focus:ring-4 focus:ring-indigo-500/5 focus:outline-none transition-all text-sm font-bold"
                  />
                </div>
              </div>

              <div className="space-y-5 p-5 bg-indigo-50/50 rounded-3xl border border-indigo-100 animate-in zoom-in-95 duration-300">
                <p className="text-[10px] font-black text-indigo-600 uppercase tracking-widest">Church Registry Details</p>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div className="md:col-span-2">
                    <label className="block text-[10px] font-black text-slate-500 mb-1.5 uppercase">Church Legal Name</label>
                    <input 
                      required
                      type="text" 
                      value={newChurchName}
                      onChange={(e) => setNewChurchName(e.target.value)}
                      placeholder="Grace Fellowship Center Int'l"
                      className="w-full px-5 py-3 bg-white border border-slate-200 rounded-xl focus:border-indigo-500 focus:outline-none text-sm font-bold"
                    />
                  </div>

                  <div>
                    <label className="block text-[10px] font-black text-slate-500 mb-1.5 uppercase">Official Phone</label>
                    <input 
                      required
                      type="tel" 
                      value={churchPhone}
                      onChange={(e) => setChurchPhone(e.target.value)}
                      placeholder="+234 800 000 0000"
                      className="w-full px-5 py-3 bg-white border border-slate-200 rounded-xl focus:border-indigo-500 focus:outline-none text-sm font-bold"
                    />
                  </div>

                  <div>
                    <label className="block text-[10px] font-black text-slate-500 mb-1.5 uppercase">Country</label>
                    <input 
                      required
                      type="text" 
                      value={churchCountry}
                      onChange={(e) => setChurchCountry(e.target.value)}
                      placeholder="e.g. Nigeria"
                      className="w-full px-5 py-3 bg-white border border-slate-200 rounded-xl focus:border-indigo-500 focus:outline-none text-sm font-bold"
                    />
                  </div>

                  <div>
                    <label className="block text-[10px] font-black text-slate-500 mb-1.5 uppercase">State / Province</label>
                    <input 
                      required
                      type="text" 
                      value={churchState}
                      onChange={(e) => setChurchState(e.target.value)}
                      placeholder="e.g. Lagos"
                      className="w-full px-5 py-3 bg-white border border-slate-200 rounded-xl focus:border-indigo-500 focus:outline-none text-sm font-bold"
                    />
                  </div>

                  <div>
                    <label className="block text-[10px] font-black text-slate-500 mb-1.5 uppercase">City</label>
                    <input 
                      required
                      type="text" 
                      value={churchCity}
                      onChange={(e) => setChurchCity(e.target.value)}
                      placeholder="e.g. Ikeja"
                      className="w-full px-5 py-3 bg-white border border-slate-200 rounded-xl focus:border-indigo-500 focus:outline-none text-sm font-bold"
                    />
                  </div>
                </div>
              </div>

              <button 
                type="submit"
                className="w-full bg-indigo-600 text-white font-black py-4 rounded-2xl hover:bg-indigo-700 shadow-xl shadow-indigo-200 transition-all text-sm uppercase tracking-[0.2em]"
