    const checkHash = () => {
      const hash = window.location.hash;
      if (hash === '#platform-vault') {
        setIsSecretVisible(true);
        setIsWorkerJoin(false);
      } else if (hash.startsWith('#join-worker')) {
        const params = new URLSearchParams(hash.split('?')[1]);
