              <button 
                onClick={() => {
                  window.location.hash = '';
                  setIsWorkerJoin(false);
                  setIsSignup(false);
                }}
                className="text-xs font-black text-slate-500 hover:text-indigo-600 uppercase tracking-widest transition-colors"
              >
                ← Back to Login
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

