                <th className="px-8 py-5">Visit Date</th>
                <th className="px-8 py-5">Assignment</th>
                <th className="px-8 py-5">Status</th>
                <th className="px-8 py-5 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
